INSERT INTO `news` (`id`, `title`, `content`, `image`, `short_description`, `createdAT`, `updatedAt`) VALUES
(4, ' Công cụ THẦN KỲ xử lý mọi vấn đề làn da', 'Nhắc tới 1 hoạt chất đa năng trong điều trị các vấn đề về da như mụn, lỗ chân lông to, nám, tàn nhang, loại bỏ nếp nhăn, cải thiện làn da không đều màu, sần ráp.. cái tên nổi bật duy nhất đó chính là RETINOIDS.\r\n\r\n \r\n\r\nRetinoids không còn xa lạ trong mỹ phẩm trị liệu da nhưng Retinoids ở nồng độ lên tới 3% ứng dụng trong sản phẩm chăm sóc da tại nhà của Juliette Armand mà không hề gây bong tróc, đỏ rát hay kích ứng da đã không khỏi khiến nhiều người bất ngờ !\r\n\r\n \r\n\r\n✨ RETINOID HPR – NHỮNG ĐIỂM NỔI BẬT VÀ KHÁC BIỆT\r\n\r\n \r\n\r\nNăm 2020, bước đột phá trong ngành da liễu với sự xuất hiện của thành viên mới trong gia đình Retinoids – Retinoid HPR chính là lời giải cho các bí ẩn về sản phẩm Retinoids của Juliette Armand\r\n\r\n \r\n\r\nRetinoid HPR là dẫn xuất dạng Ester của Retinoic acid và là cách mạng của Vitamin A thế hệ mới với đầy đủ những ưu điểm của nhóm Retinoids:\r\n\r\n \r\n\r\n– Ứng dụng được ở nồng độ cao, cho kết quả mạnh như Tretinoin (chỉ dùng trong dược phẩm kê toa)\r\n\r\n– Nhưng hoạt động trên da, khả năng đem lại tác dụng phụ cực nhỏ như Retinol.\r\n\r\n– Không bong tróc, không bỏng rát, không “bừng bừng” khô đỏ và làn da cải thiện rõ rệt trong thời gian ngắn\r\n\r\n– Retinoid HPR không cần chuyển đổi nên da ở độ PH nào thì Retinoid cũng hoạt động tốt, nên có thể sử dụng chung với Vitamin C, AHA, BHA\r\n\r\n– Retinoid HPR hoạt động với cơ chế là một thành phần liên kết tế bào, trung hòa các gốc tự do tác dụng không chỉ chống oxy hóa, ngừa nám mà còn sửa chữa và phục hồi các tổn thương, tăng miễn dịch cho da\r\n\r\n– Không gây nhiễm độc khi sử dụng ban ngày\r\n\r\n– Sử dụng lâu dài an toàn\r\n\r\n \r\n\r\n✨ 3 sản phẩm Retinoids điều trị da tại nhà HOT nhất của Juliette Armand:\r\n\r\n▪️ Retinoid C serum – Tinh chất Retinoid C phục hồi chống oxy hóa\r\n\r\n▪️ Retinoid C cream – Kem Retinoid C tái tạo, chống oxy hóa\r\n\r\n▪️ Retinoid 3% serum – Tinh chất Retinoid 3% trẻ hóa xóa nhăn', 'Bai-1.-Su-kien-workshop-1-1.jpg', '💎 Công cụ THẦN KỲ xử lý mọi vấn đề làn da  Gọi tên 3 siêu phẩm RETINOIDS nhà Juliette Armand 💎', '2024-01-24', '2024-01-31'),
(5, 'Dọn sạch “sần vỏ cam”– Trả lại thân hình thon gọn như ý', '💥 Dọn sạch “sần vỏ cam” – Trả lại thân hình thon gọn như ý\r\n\r\nCùng trị liệu B01 – Giảm mỡ cục bộ Fat & Cellulite 💥\r\n\r\nỨng dụng công nghệ cấy tinh chất tầng sâu Fat & Cellulite hủy mỡ giúp #hóa_lỏng_mỡ & chuyển hóa mỡ thành năng lượng, đặc biệt hiệu quả với tình trạng mỡ cứng – Cellulite cùng các tác động:\r\n\r\n▶️ Giảm béo trúng đích\r\n\r\n▶️ Hủy mở cứng đầu, săn chắc làn da\r\n\r\n▶️ Thải độc cơ thể, chống tích nước\r\n\r\n▶️ An toàn không phẫu thuật\r\n\r\n📌 Mỡ cứng – Cellulite là gì?\r\n\r\n– Mỡ cứng hình thành do sự tích lũy độc tố trong cơ thể từ các yếu tố: tuổi tác, gene, hormone, chế độ ăn uống hoặc lối sống trì trệ thiếu hoạt động. Cellulite đặc biệt dễ hình thành với thể trạng tuần hoàn suy giảm hay huyết áp thấp.\r\n\r\n– Đặc điểm cấu tạo mỡ cứng là các tế bào mỡ bị bao bọc bởi nhiều lớp màng độc tố. Những màng độc tố này hình thành do sự tích tụ của dịch thải tế bào tù đọng tại 1 vùng cơ thể mà không được vận chuyển đi và tiêu huỷ.\r\n\r\n– Theo thời gian, chúng liên kết chặt chẽ lại, tạo thành những lớp màng cứng bao bọc các tế bào mỡ mềm. Lớp màng độc tố này dần dần dày lên, phình to, chen chúc tập hợp dưới da làm cho da không còn bằng phẳng mà hình thành hiện tượng lồi lõm, thường được gọi bằng cái tên phổ biến: sần vỏ cam.\r\n\r\n– Sần vỏ cam xuất hiện phổ biến nhất ở vùng đùi, mông và bắp tay nhưng trong một số trường hợp đặc biệt ta cũng tìm thấy ở vùng bụng.\r\n\r\n📌 Bấp chấp mọi tình trạng mỡ & Cellulite, liệu trình B01 – Giảm mỡ cục bộ Fat & Cellulite của JA sẽ đều xứ lý nhanh gọn:\r\n\r\n– Liệu pháp tích hợp công nghệ dẫn chất AHA và đầu kim siêu nhỏ giúp kích hoạt tế bào ở mức tối đa để tích cực thúc đẩy quá trình làm tan mỡ.\r\n\r\n– Tổ hợp các hoạt chất Biogenic Caffein thủy phân acid béo chyển hóa thành acid béo tự do, chống tích mỡ cục bộ, chống cellulite và trùng nhão.\r\n\r\n– L- carnitine giúp chuyển hóa các chất béo thừa thành năng lượng & 4 Peptide sinh học gồm Tripeptide 41 ngăn ngừa tích mỡ, Decapeptide 4 tăng đàn hồi da và Oligo Peptide 51, 61 thúc đẩy hoạt động tổng thể của các hợp chất.\r\n\r\n– Vùng mỡ mềm dần đi, các mô mỡ dễ dàng được phá tan và chuyển hóa mỡ thành dịch lỏng và được đào thải dễ dàng qua hệ thống màng lọc bạch huyết.\r\n\r\n📌 Sản phẩm về nhà – Duy trì số đo mơ ước:\r\n\r\n🌟 𝐓𝐫𝐢𝐩𝐥𝐞 𝐀𝐜𝐭𝐢𝐨𝐧 𝐒𝐡𝐚𝐩𝐞 𝐆𝐞𝐥\r\n\r\nSản phẩm cải thiện các đường nét cơ thể và tăng cường kết cấu của da. Các hoạt chất có tính năng kích hoạt tức thì quá trình hủy mỡ, làm giảm cellulite và ngăn ngừa chảy sệ da với hiệu quả rõ rệt\r\n\r\n🌟 𝐒𝐭𝐫𝐞𝐭𝐜𝐡 𝐅𝐢𝐫𝐦 𝐂𝐫𝐞𝐚𝐦\r\n\r\nSản phẩm lấy lại độ đàn hồi của da và làm giảm sự xuất hiện của các vết rạn da, đồng thời chống lại celluliite, củng cố mô liên kết, đốt cháy và hóa lỏng mỡ và làm săn chắc da tức thì', 'Z-Flip-6-FE-4.jpg', '💥 Dọn sạch “sần vỏ cam” – Trả lại thân hình thon gọn như ý  Cùng trị liệu B01 – Giảm mỡ cục bộ Fat & Cellulite 💥', '2023-11-14', '2023-11-14'),
(6, 'TRỌN BỘ SẢN PHẨM ĐIỀU TRỊ DẬP TẮT CƠN KÍCH ỨNG', 'TRỌN BỘ SẢN PHẨM ĐIỀU TRỊ\r\n\r\n👊 DẬP TẮT CƠN KÍCH ỨNG 👊\r\n\r\n \r\n\r\nDa dễ kích ứng, da nhạy cảm chính là điều khiến bất kì ai cũng phải ngần ngại mỗi khi quyết định mua một sản phẩm dưỡng da hay thử sức mới một liệu trình làm đẹp nào.\r\n\r\n \r\n\r\nThông thường khi dị ứng, làn da thường có đặc trưng là nổi mẩn những nốt đỏ, mụn nước li ti gây ngứa, sần sùi khó chịu, đôi khi là nổi sưng những cục mụn to, da bong tróc do khô, có thể có cảm giác nóng rát, khó chịu\r\n\r\n \r\n\r\nĐể tránh tình trạng thêm nặng, JA có những công thức dập tắt kích ứng đã được khách hàng kiểm chứng & công nhận hiệu quả giúp làn da được làm dịu ngay lập tức khỏi các biểu hiện kích ứng, nuôi dưỡng & duy trì nền da khỏe đẹp:\r\n\r\n \r\n\r\n🛡 Công thức cấp cứu làn da kích ứng tại Spa:\r\n\r\nSữa rửa mặt dịu nhẹ – Thoa B complex serum ( hoặc B9, hoặc D3) – Đắp Clarifying Mask – Bôi Caliming Bliss\r\n\r\n🛡 Công thức cấp cứu làn da kích ứng tại nhà:\r\n\r\nSữa rửa mặt dịu nhẹ – Đắp lô hội làm dịu và cấp ẩm – Thoa B complex serum ( hoặc B9, hoặc D3) – Bôi calming Bliss\r\n\r\n==============\r\n\r\n🛡 Tinh chất Folic Acid B9 serum chống kích ứng\r\n\r\n* Sử dụng cho mọi loại da, đặc biệt khuyên dùng với da dầu mụn lâu lành, da dễ kích ứng hoặc mẩn ngứa, da sau lột tẩy, laser … Ngay lập tức giúp làm dịu làn da đang bị kích ứng, đỏ, rát, bỏng nắng …\r\n\r\n* Dùng lâu dài sp có khả năng làm khỏe miễn dịch, ổn định các chức năng của da, cho da bóng khoẻ & đồng nhất\r\n\r\n \r\n\r\n🛡 Tinh chất Provital D3 serum bảo vệ đa chiều.\r\n\r\n* Sử dụng cho mọi loại da, kể cả da dầu, đặc biệt nên sử dụng cho da sau kích ứng, da bị chứng đỏ da, da dễ xạm khi đi nắng hoặc thường xuyên phải đi nắng, da có nám tiềm ẩn… Ngay lập tức giúp làm dịu làn da đang bị kích ứng, đỏ, rát, bỏng nắng, viêm da dị ứng hoặc chàm eczema…\r\n\r\n* D3 sử dụng lâu dài làm khỏe hàng rào bảo vệ da, chống tác hại của UVA, UVB\r\n\r\n \r\n\r\n🛡 Tinh chất vitamin B tổng hợp làm dịu da nhạy cảm và kích ứng.\r\n\r\n* Lý tưởng cho da hỗn hợp, da thường khô mỏng yếu, giãn nở mao mạch, da nhiễm corticoid bị teo mỏng và suy giảm miễn dịch, da hỗn hợp mụn nhạy cảm.\r\n\r\n* Hỗn hợp các vitamin nhóm B (1,2,3,5,6,12) ổn định các chức năng da, tăng miễn dịch & làm dịu tức thì làn da đang bị kích ứng, đỏ, rát, ngứa …\r\n\r\n* Vitamin B3, redyless & panthenol giảm đỏ, đốm đỏ, đốm xuất huyết, làm khoẻ thành mạch, giảm hiện tượng mụn đỏ kèm mạch máu giãn nở vùng mũi….\r\n\r\n \r\n\r\n🛡 Mặt nạ Clarifying Mask\r\n\r\n* Sản phẩm giải quyết da khỏi sưng viêm và kích ứng nghiêm trọng. Kết hợp thành phần đất sét và dẫn xuất axit salicylic đặc biệt, panthenol, lô hội và cúc La Mã giúp da giảm sưng tấy và kích ứng tức thì.\r\n\r\n* Thành phần Normaseb thủy phân từ protein sữa, giàu axit amin (cystine và methionine) và vitamin B6 giúp phục hồi lớp màng lipid bảo vệ da.\r\n\r\n* Sản phẩm cũng được khuyên dùng ngay sau các trị liệu làm sạch sâu (lột tẩy).\r\n\r\n \r\n\r\n🛡 Calming Bliss: Kem đặc trị làm dịu, kháng viêm và phục hồi da sau xâm lấn\r\n\r\n* Dành cho mọi loại da sau peel, sau các trị liệu xâm lấn hoặc da kích ứng cấp, viêm sưng trên nền da yếu nhạy cảm, dễ kích ứng trong giai đoạn bất ổn\r\n\r\n* Ngay lập tức làm dịu làn da đỏ rát, sưng tấy hoặc da sau peel, kim, laser…\r\n\r\n* Methyl salicylate làm dịu mạnh và chống viêm. Cúc La mã, Panthenol, chiết xuất rau má, lô hội giúp kháng viêm, dưỡng ẩm và sửa chữa các tổn thương\r\n\r\n———————–', 'Bai-2-1-1.jpg', 'TRỌN BỘ SẢN PHẨM ĐIỀU TRỊ  👊 DẬP TẮT CƠN KÍCH ỨNG 👊', '2023-11-18', '2023-11-18'),
(7, 'RA MẮT TRỊ LIỆU MỚI JULIETTE ARMAND', '🔥 RA MẮT TRỊ LIỆU MỚI JULIETTE ARMAND\r\n\r\n🔥 PHÁ MỠ – ĐỊNH HÌNH VÓC DÁNG – HOT NHẤT HÈ NÀY\r\n\r\n✔️ Tham dự ngay #workshop chuyển giao \r\n\r\n✔️ Phác đồ PHÁ MỠ và đào thải liên tục, ĐỊNH HÌNH VÓC DÁNG THON GỌN – SĂN CHẮC – MỜ RẠN nhờ bộ siêu hoạt chất thế hệ mới để đón đầu xu hướng trị liệu giảm béo 2021 này \r\n\r\n👉 #Đăng_ký nhận ngay VÉ MIỄN PHÍ tham dự chương trình tại: https://bit.ly/35rIxI5\r\n\r\nMùa hè được coi là “thời điểm vàng” giảm béo của năm. Đồng nghĩa với việc, các dịch vụ trị liệu về vóc dáng tại Spa sẽ trở nên có sức hút vô cùng mạnh mẽ với khách hàng. \r\n\r\nNgay lúc này, việc sở hữu “vũ khí nặng đô” – xử lý #gọn mọi hình thái mỡ, am hiểu tường tận về cơ chế khoa học đào thải mỡ thừa & nắm bắt những điều mấu chốt trong nguyên lý hủy mỡ, tránh những thất bại không đáng có trong trị liệu là điều tối cần thiết \r\n\r\n👉 Tất cả sẽ được “mổ xẻ” tại Workshop chuyển giao phác đồ PHÁ MỠ VÀ ĐÀO THẢI LIÊN TỤC, ĐỊNH HÌNH VÓC DÁNG THON GỌN – SĂN CHẮC – MỜ RẠN NHỜ BỘ SIÊU HOẠT CHẤT THẾ HỆ MỚI tổ chức ngày 23/3 tới này của Juliette Armand 👇\r\n\r\n🔥 TOPIC CHÍNH ĐƯỢC CHIA SẺ TRONG CHƯƠNG TRÌNH:\r\n\r\n1. Phân loại hình thái vóc dáng.\r\n\r\n2. Cơ chế chuyển hoá & dự trữ mỡ của cơ thể.\r\n\r\n3. Sự khác biệt của mỡ cứng – cellulite & mỡ mềm và các nguy cơ bệnh lý.\r\n\r\n4. Cơ chế hình thành sẹo rạn và mô cơ chảy xệ.\r\n\r\n5. Nguyên lý điều trị phá mỡ – đào thải mỡ thừa – cải thiện mô sẹo rạn và kích thích co cơ.\r\n\r\n6. Phác đồ sửa chữa vóc dáng chuẩn.\r\n\r\n7. Demo trị liệu & nhận chứng nhận tham dự chương trình.\r\n\r\n📌 THỜI GIAN: 13h00 – 17h00 ngày 23/03/2021\r\n\r\n📌 ĐỊA ĐIỂM: Riverside Hanoi Hotel, 118 Nguyễn Đình Hoàn, Nghĩa Đô, Cầu Giấy, Hà Nội\r\n\r\n👉 #INBOX JA để được hỗ trợ thông tin chi tiết về chương trình.\r\n\r\n👉 #Hotline hỗ trợ: 0911 463 588\r\n\r\n———————–\r\n\r\n➤ Juliette Armand – Mỹ phẩm trị liệu hàng đầu Hy Lạp\r\n\r\n➤ Website: https://juliettearmand.vn/', 'Bai-1.-Su-kien-workshop-1-1.jpg', '🔥 RA MẮT TRỊ LIỆU MỚI JULIETTE ARMAND  🔥 PHÁ MỠ – ĐỊNH HÌNH VÓC DÁNG – HOT NHẤT HÈ NÀY', '2024-02-01', '2024-02-27'),
(8, 'Tháo gỡ các “nút thắt” trong quá trình điều trị nám và cải thiện sắc tố', '💡 Tháo gỡ các “nút thắt” trong quá trình điều trị nám và cải thiện sắc tố 💡\r\n\r\n➡️ Chỉ có tại chương trình Đào Tạo Zoom ngày 17.3 & 24.3 này ⬅️\r\n\r\n🔥 Đăng ký ngay: https://bit.ly/35rIxI5\r\n\r\nNám luôn là một chủ đề hot, một vấn đề khiến không ít chủ Spa kiêng dè và thận trọng. Đặc biệt với đặc thù da và môi trường Việt Nam: nắng, nóng, thời tiết bất thường, ô nhiễm không khí,…\r\n\r\nĐã đến lúc tháo bỏ các nút thắt trong quá trình điều trị nám cho khách hàng cùng chuyên gia Juliette Armand:\r\n\r\n💡 Nắm vững “chủng loại” và tập tục của nám để phát hiện và phân loại\r\n\r\n💡 Từ phân loại, có thể chọn ra vũ khí thích hợp nhằm xoá bỏ và ngăn ngừa hình thành nám, cải thiện sắc tố\r\n\r\n💡 Những nguyên nhân thất bại LỚN NHẤT trong điều trị nám\r\n\r\n💡 Thủ thuật xử lý khi gặp vấn đề trong quy trình trị nám\r\n\r\n🔥 Chỗ trống CÓ HẠN, vui lòng liên hệ đặt lịch:\r\n\r\n➡️ Inbox: https://bit.ly/35rIxI5\r\n\r\n➡️ Hoặc liên hệ nhân viên kinh doanh\r\n\r\n———————–\r\n\r\n➤ Juliette Armand – Mỹ phẩm trị liệu hàng đầu Hy Lạp\r\n\r\n➤ Website: https://juliettearmand.vn/', 'Bai-2.-Dao-tao-Zoom.jpg', '💡 Tháo gỡ các “nút thắt” trong quá trình điều trị nám và cải thiện sắc tố 💡  ➡️ Chỉ có tại chương trình Đào Tạo Zoom ngày 17.3 & 24.3 này ⬅️', '2024-02-01', '2024-02-20'),
(9, 'Chuẩn hóa phác đồ Căng bóng – Trị mụn – Xóa nám', '👑 Chuẩn hóa phác đồ Căng bóng – Trị mụn – Xóa nám\r\n\r\nVới phương pháp PEEL – Tái tạo nền da vượt trội từ JA 👑\r\n\r\nPeel da được biết đến là một liệu pháp trị liệu thẩm mỹ tác động lên cấu trúc thượng bì của làn da làm cho lớp tế bào cũ trên da bong tróc, làn da được thay mới, các khuyết điểm mờ dần, da sáng và mịn màng hơn.\r\n\r\nTại Juliette Armand, phương pháp này được ứng dụng vô cùng linh hoạt, đặc biệt, với bộ công cụ đa dạng tương ứng cho từng tình trạng da với các vấn đề khác nhau:\r\n\r\n✔️ Trị liệu Peel cho nền da yếu, khô & mụn ẩn\r\n\r\n✔️ Trị liệu Peel cho da có nhiều ổ mụn viêm sâu, cần tiêu viêm và cô cồi mụn giảm nguy cơ sẹo sau mụn\r\n\r\n✔️ Trị liệu Peel cho da nám, tàn nhang & rối loạn sắc tố\r\n\r\n👉 Tháng 1 này, tham dự ngay WORKSHOP chuyển giao CÔNG NGHỆ PEEL AN TOÀN – LÀM MỚI NỀN DA – BÓNG KHỎE RẠNG NGỜI để thuần thục ứng dụng 3 kỹ thuật Peel da chuẩn khoa học áp dụng cho 3 tình trạng da cơ bản trong điều trị da liễu – Làm chủ hoạt chất – chuẩn hóa các phác đồ trị liệu với sự đào tạo trực tiếp từ chuyên gia Phạm Phương Linh – GĐ Juliette Armand.\r\n\r\n🔥 Nội dung chính không thể bỏ lỡ trong chương trình:\r\n\r\n▪️ Sự khác nhau giữa các phương pháp Peel (sinh học, hoá học, vật lý …)\r\n\r\n▪️ Vai trò của PH đối với làn da\r\n\r\n▪️ Hoạt tính và mức độ tác động của các liệu pháp Peel JA\r\n\r\n▪️ Tối ưu hoá phác đồ thay nền da hiệu ứng bóng khoẻ rạng ngời\r\n\r\n▪️ Hướng dẫn kỹ thuật Peel an toàn chuẩn JA\r\n\r\nLịch tổ chức chương trình:\r\n\r\n🔺 Tại HCM:\r\n\r\nThời gian: 8h30 – 16h30, ngày 5/01/2021\r\n\r\nĐịa điểm: 763 Lê Hồng Phong, P.12, Q10, HCM\r\n\r\n🔺 Tại Hà Nội:\r\n\r\nThời gian: 8h30 – 16h30, ngày 12/01/2021\r\n\r\nĐịa điểm: Biệt thự A10 – khu Đô thị Trung Hoà Nhân Chính – Q.Cầu Giấy – HN\r\n\r\n🔥 #Nhận_Thư_mời tại: goo.gl/itvKbn\r\n\r\n🔥 #Đăng_kí_giữ_chỗ: 0911 463 588\r\n\r\n———————–\r\n\r\n➤ Juliette Armand – Mỹ phẩm trị liệu hàng đầu Hy Lạp\r\n\r\n➤ Website: https://juliettearmand.vn/', 'bai-3-3.jpg', '👑 Chuẩn hóa phác đồ Căng bóng – Trị mụn – Xóa nám  Với phương pháp PEEL – Tái tạo nền da vượt trội từ JA 👑', '2024-01-03', '2024-02-27');

