--
-- Table structure for table `products`
--

CREATE TABLE `products` (
  `idProduct` int(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `costPrice` varchar(50) DEFAULT NULL,
  `sellingPrice` varchar(50) NOT NULL,
  `benifit` varchar(1000) DEFAULT NULL,
  `descride` varchar(1000) DEFAULT NULL,
  `introduce` varchar(2550) NOT NULL,
  `object` varchar(1255) NOT NULL,
  `instruct` varchar(1255) NOT NULL,
  `note` varchar(2550) NOT NULL,
  `tag` varchar(255) NOT NULL,
  `sellNumber` int(50) NOT NULL,
  `qttStock` int(50) NOT NULL DEFAULT 0,
  `createdAt` date NOT NULL DEFAULT current_timestamp(),
  `updatedAt` date NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

