INSERT INTO `products` (`idProduct`, `name`, `image`, `costPrice`, `sellingPrice`, `benifit`, `descride`, `introduce`, `object`, `instruct`, `note`, `tag`, `sellNumber`, `qttStock`, `createdAt`, `updatedAt`) VALUES
(1, 'Brightening Serum Juliette Armand', '1.jpg', '1950000', '1755000', 'Brightening serum juliette armand Lợi ích Serum Juliette Armand Brightening Làm sáng và ức chế hình thành nám.\r\n\r\nGiúp làm mịn bề mặt da, làm mờ các đốm thẫm màu và làm đều màu da.\r\n\r\nCó thể dùng cho chăm sóc phòng ngừa nám với những làn da', 'Brightening serum juliette armand là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand AHA Smoothing đến từ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam.Kem trẻ hóa da Juliette Armand Aha Smoothing Cream giúp cấp nước và thúc đẩy quá trình trẻ hóa tự nhiên của làn da, giúp làm săn chắc và mịn màng.\r\nKem trẻ hóa da Juliette Armand AHA Smoothing Cream – giải pháp mang đến một làn da căng mịn và tươi sáng cho nàng.\r\n\r\nJuliette Armand AHA Smoothing Cream có chứa AHA giúp lột tẩy nhẹ, kích thích tái sinh làn da mới. Keratoplast, Hyaluronic acid, chiết xuất rau má và lô hội giúp cấp nước và thúc đẩy quá trình trẻ hóa tự nhiên của làn da, giúp làm săn chắc và mịn màng.\r\n\r\nMột loại kem phục hồi chức năng mịn màng của da, dựa trên sự lựa chọn cụ thể của nhiều hàm lượng AHA (axit lactic, glycolic và mandelic) với độ pH 5,0 kết hợp với thành phần keratoplast. Được tăng cường với axit hyaluronic MMW, Panthenol, Chiết xuất Centella và Aloe Vera, nó thúc đẩy quá trình trẻ hóa tự nhiên của da và cấp nước, làm cho da rạng rỡ, thúc đẩy quá trình trẻ hóa tự nhiên của làn da, giúp làm săn chắc và mịn màng.. Nó có đặc điểm là rất đàn hồi và dễ dàng hấp thụ mà không để lại da nhờn. Nó được khuyến khích để được kết hợp với bảo vệ chống nắng.', 'Đối tượng AHA smoothing cream juliette armand Đối tượng Kem mặt Juliette Armand AHA Smoothing Kem dưỡng Juliette Armand AHA Smoothing Cream được sử dụng cho mọi loại da. Đặc biệt da bị lão hóa và da khô.', 'Hướng dẫn sử dụng AHA smoothing cream juliette armand Hướng dẫn sử dụng Kem mặt Juliette Armand AHA Smoothing Rửa mặt sạch trước khi sử dụng\r\nThoa một lượng nhỏ sản phẩm lên toàn mặt 1 đến 2 lần mỗi ngày.', 'Thành phần và lưu ý Kem mặt Juliette Armand AHA Smoothing\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da.\r\nHyaluronic aicid MMW: tăng cường độ ẩm mà không chất nào có thể so sánh, giúp hồi phục các lớp tế bào ở bề mặt da để da trông mềm mại, mịn màng và ngậm nước hơn. Chính điều này giúp cải thiện đáng kể việc xuất hiện sớm của nếp nhăn cùng các dấu hiệu lão hóa sớm khác\r\nCentella Asiatica: có khả năng giúp chữa lành và làm dịu da, kháng khuẩn, kháng viêm. Bên cạnh đó, chiết xuất của cây rau má còn có tác dụng rất tốt trong điều trị các bệnh về da như chàm, vẩy nến và sẹo; đồng thời chất này còn dưỡng ẩm rất hiệu quả, đặc biệt phù hợp cho các loại da khô.\r\nLactic acid: lactic acid có khả năng ngậm nước. Do đó, lactic acid giúp cấp ẩm, dưỡng ẩm cho da tốt hơn, giảm vấn đề khô da sau khi sử dụng mà thường gặp ở các AHA khác.\r\nGlycolic acid: giúp hòa tan các liên kết, giữ tế bào da với nhau, cho phép các tế bào da chết bong ra nhanh hơn so với quy trình tự nhiên. Hơn nữa, glycolic axit cũng kích thích làn da tạo ra nhiều collagen. Collagen là một loại protein mang lại cho làn da sự săn chắc, căng mọng và đàn hồi.\r\nMandelic acid: Làm mềm lớp sừng và tẩy tế bào chết, nhờ đó giúp da sang và đều màu hơn.\r\nThành phần đầy đủ: Aqua, C12-20 Acid Peg-8 Ester , Butylene Glycol, Glycolic Acid, Sodium Hydroxide, Aloe Barbadensis Leaf Extract, Lactic Acid, Isotridecyl Salicylate, Polyisoprene, Hydroxyethylcellulose, Glyceryl Stearate, Peg-100 Stearate , Mandelic Acid, Sodium Acrylate/Acryloyldimethyltaurate/Dimethylacrylamide Crosspolymer, Phenoxyethanol, Isohexadecane, Dimethicone, Caprylyl Glycol, Ethylhexylglycerin, Parfum, Bisabolol, Centella Asiatica Leaf Extract, Polysorbate 60, Sodium Benzoate, Sodium Hyaluronate, Sodium Citrate, Citric Acid Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 3, 100, '2024-02-08', '2024-02-18'),
(2, 'BHA Paula’s Choice Mini', '2.jpg', '399000', '399000', 'Loại bỏ tế bào chết và các tạp chất tồn đọng, từ đó giảm bít tắc, giúp da trở nên thông thoáng.\r\nĐiều tiết lượng bã nhờn dư thừa, hỗ trợ thu nhỏ lỗ chân lông.\r\nCó hoạt tính tương tự như một chất kháng khuẩn, hỗ trợ cải thiện tình trạng mụn trên da, đặc biệt là mụn ẩn và mụn đầu đen.\r\nLàm đều màu da và làm mờ nếp nhăn sâu.', 'BHA là tên viết tắt của Beta Hydroxy Acid. Đặc điểm nổi bật của thành phần loại bỏ tế bào chết này đó là tan trong dầu và hoạt động bên trong lỗ chân lông để giải quyết tình trạng bít tắc. Vậy nên làn da dầu, lỗ chân lông to và bề mặt da không mịn màng thường được giải quyết bằng BHA.\r\n\r\nBHA phổ biến nhất là Salicylic Acid, phần lớn được chiết xuất từ vỏ cây liễu, dầu của cây lộc đề xanh. Chúng đều có nguồn gốc từ tự nhiên nhiều tác dụng và có lợi cho làn da. Trong các sản phẩm chăm sóc da với thành phần chính là BHA, nồng độ pH của da càng thấp thì hiệu quả của BHA mang lại sẽ tốt hơn và tương ứng với đó là nồng độ BHA thông thường 0.5% – 2%.', 'Đây là một trong những tác dụng đầu tiên của loại bỏ tế bào chết BHA trên da. Với đặc tính đi sâu bên trong lỗ chân lông nên khi sử dụng loại bỏ tế bào chết BHA sẽ giúp loại bỏ bụi bẩn, dầu thừa tích tụ bấy lâu nay. Những yếu tố gây bít tắc lỗ chân lông và nguy cơ dẫn đến mụn đã được đẩy lùi sớm nhờ thành phần BHA hoạt động tích cực.\r\n\r\nKhác với phương pháp loại bỏ tế bào chết truyền thống, tác động bên trên bề mặt da và có thể gây chà xát, làm tổn thương da khiến da kích ứng, nhạy cảm thì BHA có thể đi sâu vào bên trong lỗ chân lông, cải thiện kích thước lỗ chân lông.', 'Sản phẩm phù hợp cho mọi loại da.', 'Da dễ tắc lỗ chân lông\r\nDa mụn đầu đen\r\nDa dầu thừa – lỗ chân lông to\r\nDa lão hóa, có nếp nhăn\r\nDa không đều màu', 'Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.\r\nĐậy nắp kín sau khi sử dụng.\r\nDung tích: 30ml (mini size)\r\n\r\nThương hiệu: Paula’s Choice\r\n\r\nXuất xứ thương hiệu: Mỹ\r\n\r\nSản xuất tại: Mỹ', 'NEW', 5, 100, '2023-12-08', '2024-02-08'),
(3, 'Bio Placenta Serum Juliette Armand Tinh Chất Trẻ Hóa Da', '3.jpg', '1550000', '1395000', 'Lợi ích Juliette armand bioplacenta serum Lợi ích Serum Juliette Armand Bio Placenta Giữ ẩm\r\nKích thích tổng hợp collagen nguyên bào sợi\r\nNhanh chóng làm lành các tổn thương nhờ gia tăng quá trình tái tạo và liên kết tự nhiên của tế bào\r\nGiúp trẻ hóa và mang tới 1 làn da bóng khỏe.', 'Juliette armand bioplacenta serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Serum Juliette Armand Bio Placenta Juliette Armand Bio Placenta Serum với công thức phỏng sinh học (tương tự nhau thai người) được hình thành từ khuẩn lên men và chứa đầy đủ các yếu tố tăng trưởng. Sản phẩm giúp giữ ẩm, kích thích tổng hợp collagen nguyên bào sợi, nhanh chóng làm lành các tổn thương nhờ gia tăng quá trình tái tạo và liên kết tự nhiên của tế bào, giúp trẻ hóa và mang tới 1 làn da bóng khỏe.\r\n\r\nNó giúp dưỡng ẩm và tăng cường chức năng đổi mới tự nhiên và tính nhất quán của da, cải thiện vẻ ngoài và sức sống của da. Serum có chứa thành phần mô phỏng sinh học (Bioplacenta), có nguồn gốc từ quá trình lên men vi khuẩn, với năm yếu tố tăng trưởng khác nhau (EGF, IGF-1, FGF có tính axit, FGF cơ bản và VEGF), axit amin và vitamin B9. Nó có đặc tính chống nhăn, chống lão hóa và trẻ hóa.', 'Đối tượng Juliette armand bioplacenta serum Đối tượng Serum Juliette Armand Bio Placenta Serum tế bào gốc sinh học Juliette Armand Bio Placenta Serum 20ml an toàn, phù hợp với mọi loại da, đặc biệt các tình trang như:\r\nDa sau tổn thương cần phục hồi\r\nDa mỏng cần làm dày và tái sinh\r\nDa khô thiếu dưỡng chất, nếp nhăn, không đều màu, thiếu sức sống.', 'Hướng dẫn sử dụng Juliette armand bioplacenta serum Hướng dẫn sử dụng Serum Juliette Armand Bio Placenta Rửa sạch mặt trước khi dùng serum\r\nThoa 1 lượng nhỏ sản phẩm lên da đã làm sạch và masage cho đến khi sản phẩm được hấp thụ hết.', 'Thành phần và lưu ý Serum Juliette Armand Bia Placenta\r\nBio-Placenta 3%: Nhau thai cừu chứa rất nhiều protein, enzyme, đến hơn 30 loại amino acid, vitamin, và các yếu tố sinh trưởng tế bào giúp phục hồi da lão hóa và cải thiện tình trạng nếp nhăn, chảy xệ. Bên cạnh đó, nhau thai cừu còn chứa các thành phần chống oxy hóa giúp bảo vệ da trước tác động từ ánh sáng mặt trời, từ môi trường. Củng cố hệ mạng lưới collagen, elastin duy trì độ đàn hồi cho da. Đồng thời nuôi dưỡng và thay thế các thế bào già cỗi hoặc bị tổn thương, giúp da luôn căng mịn và được trẻ hóa. Trong nhau thai cừu, chứa hàm lượng cao các loại vitamin, khoáng chất. Đặc biệt là các vitamin A, vitamin E, vitamin D,… giúp nuôi dưỡng làn da từ sâu bên trong, hỗ trợ tái tạo da và tăng độ sáng da. Nhau thai cừu có tác dụng tích cực trong việc tạo hồng cầu máu, giúp tăng độ sáng mịn, hồng hào cho da. Giúp cải thiện các đốm nám, tàn nhang và ức chế sự hình thành, gia tăng sắc tố melanin. Các thành phần trong nhau thai cừu có tác dụng bổ sung dưỡng chất cho da, giúp duy trì cấu trúc màng tế bào da. Thúc đẩy hoạt động của các tế bào, giúp da đào thải độc tốt và hấp thu dưỡng chất một cách tốt hơn. Tại Úc nhờ thuận tiện trong điều kiện tự nhiên và thời tiết, hoạt động chăn nuôi cừu tự nhiên phát triển mạnh. Nhờ đó, nhau thai cừu Úc cũng được ứng dụng mạnh mẽ trong nhiều sản phẩm làm đẹp, nổi tiếng trên thế giới.\r\n\r\nSau quá trình tinh chế và sản xuất các nhà nghiên cứu Rosien cũng lựa chọn thành phần nhau thai cừu làm thành phần chủ chốt trong nhiều sản phẩm. Giúp bổ sung dưỡng chất cho làn da tăng cường khả trẻ hóa và gìn giữ thanh xuân cho phái đẹp. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 9, 50, '2023-12-08', '2024-01-08'),
(4, 'Brightening Serum Juliette Armand', '4.jpg', '2050000', '1845000', 'Brightening serum juliette armand Lợi ích Serum Juliette Armand Brightening Làm sáng và ức chế hình thành nám.\r\nGiúp làm mịn bề mặt da, làm mờ các đốm thẫm màu và làm đều màu da.\r\nCó thể dùng cho chăm sóc phòng ngừa nám với những làn da', 'Brightening serum juliette armand là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Tinh chất làm sáng da Juliette Armand Brightening Serum làm sáng và ức chế hình thành nám, giúp làm mịn bề mặt da, làm mờ các đốm nâu và làm đều màu da.\r\nTinh chất làm sáng da Juliette Armand Brightening Serum chứa các hợp chất làm sáng và ức chế hình thành nám, giúp làm mịn bề mặt da, làm mờ các đốm nâu và làm đều màu da. Có thể dùng cho chăm sóc phòng ngừa nám với những làn da bị oxy hoá mạnh và đã hình thành chân nám..\r\n\r\nBrightening Serum cải thiện vẻ ngoài của da và mang lại một làn da trắng sáng hơn. Một loại huyết thanh có chứa Asyntra (Hexylresorcinol và Ethyl Linoleate), axit Gallic, axit Phytic, Vitamin C, Rumex và cam thảo, những thành phần này kết hợp với nhau mang lại màu da đồng nhất. Tác dụng hiệp đồng của các thành phần nhằm mục đích ức chế enzym tyrosinase chịu trách nhiệm sản xuất melanin và tăng cường hoạt động chống oxy hóa, củng cố cơ chế bảo vệ tế bào khỏi các tình trạng viêm gây ra các đốm sắc tố.', 'Đối tượng Serum Juliette Armand Brightening Juliette Armand Brightening Serum là tinh chất sáng da, giảm nám với thành phần an toàn và lành tính phù hợp với mọi loại da.\r\n\r\nĐặc biệt phù hợp các làn da:\r\n\r\nDa xỉn màu, không đều màu\r\nDa bắt đầu xuất hiện các dấu hiệu lão hóa: nám, tàn nhang, đồi mồi,…', 'Hướng dẫn sử dụng Brightening serum juliette armand Hướng dẫn sử dụng Serum Juliette Armand Brightening Làm sạch da với tẩy trang và sữa rửa mặt.\r\nDùng toner để cân bằng da.\r\nThoa 1 lượng nhỏ sản phẩm lên da và massage cho đến khi thẩm thấu hết.\r\nNên kết hợp cùng Kem làm sáng da, giảm nám Juliette Armand Brightening Cream để đạt hiệu quả tốt nhất.\r\nSử dụng cả ngày và đêm.', 'Hướng dẫn sử dụng Brightening serum juliette armand Hướng dẫn sử dụng Serum Juliette Armand Brightening Làm sạch da với tẩy trang và sữa rửa mặt.\r\nChiết xuất Rumex: Một loại cây axit phương tây có nguồn gốc từ đồng cỏ Canada, là một loại dưỡng chất làm dịu da. Nó thể hoạt động hiệu quả trên da, ngăn chặn sự hình thành của tyrosinase, do đó ức chế sản xuất melanin.\r\n\r\nAxit Ascorbic (Tyrostat): Giúp da chống lại quá trình oxy hóa cũng như việc ức chế quá trình hình thành melanin, làm mờ sẹo, thâm, giúp da sáng mịn hơn.\r\n\r\nChiết xuất Cam thảo: một chất làm sáng da tự nhiên tuyệt vời mà nó còn giúp làm giảm thâm và các vùng da tối màu do sẹo để lại. Chiết xuất cam thảo có đặc tính giúp làm dịu và dưỡng ẩm cho da rất tốt vì nó có chứa Liquiritin, giúp chống lại quá trình lão hóa da, giúp da luôn trong trạng thái căng mướt, hồng hào. Ngoài ra, chiết xuất cam thảo còn phù hợp cho các loại da dầu vì tinh chất không gây bít tắc lỗ chân lông, giúp da luôn thông thoáng, dễ chịu.\r\n\r\nAxit Phytic: Phytic acid là một chất chống oxy hóa, thuộc họ axit alpha hydroxy (AHA). Nó còn thường được gọi với tên khác đó là inositol polyphosphate hoặc inositol hexakisphosphate (IP6). Từ xa xưa, phụ nữ châu Á đã biết dùng hoạt chất này để làm sáng và đều màu da.\r\n\r\nThành phần đầy đủ: Aqua, Butylene Glycol, Aloe Barbadensis Leaf Extract, Glycerin, Polyacrylamide , Ricinoleth-40, Ppg-26-Buteth-26, C13-14 Isoparaffin, Phenoxyethanol, Peg-40 Hydrogenated Castor Oil, Sodium Phytate, Caprylyl Glycol, Ethylhexylglycerin, Glycyrrhiza Glabra Root Extract, Laureth-7, Bisabolol, Caprylic/Capric Triglyceride, Ascorbic Acid, Rumex Occidentalis Extract, Ethyl Linoleate, Hexylresorcinol, Potassium Hydroxide, Diglucosyl Gallic Acid, Alcohol Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 0, 100, '2023-12-08', '2023-12-08'),
(5, 'Clarifying Stick Juliette Armand', '5.jpg', '950000', '855000', 'Clarifying stick juliette armand Lợi ích Chấm mun Juliette Armand Clarifying Stick Giảm mụn sưng viêm hiệu quả.\r\nCó kết quả ngay lập tức và mạnh mẽ đối với các nốt mụn và mụn nhọt.\r\nGiúp se khít lỗ chân lông, ngăn ngừa mụn quay trở lại', 'Clarifying stick juliette armand là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Chấm mun Juliette Armand Clarifying Stick là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam. Chấm mụn tiêu viêm sưng Juliette Armand Clarifying Stick có kết quả ngay lập tức và mạnh mẽ đối với các nốt mụn và mụn nhọt, bằng cách ức chế sự phát triển của chúng thành viêm.\r\nChấm mụn tiêu viêm sưng Juliette Armand Clarifying Stick – Một sản phẩm chuyên biệt với hàm lượng cao các thành phần hoạt tính để sử dụng tại chỗ có kết quả ngay lập tức và mạnh mẽ đối với các nốt mụn bằng cách ức chế sự phát triển của chúng thành viêm.\r\n\r\nĐồng thời, Juliette Armand Clarifying Stick với thành phần chính Acid Azelaic, Acid Salicylic giúp kháng khuẩn, kháng viêm, sạch sâu lỗ chân lông và hạn chế sự thâm sau mụn. Ngoài ra em này còn được tăng cường với Chiết xuất Mimosa và Normaseb, nó giúp trẻ hóa da nhanh hơn và điều tiết tiết bã nhờn.', 'Đối tượng Chấm mun Juliette Armand Clarifying Stick Juliette Armand Clarifying Stick phù hợp với làn da đang có mụn, đặc biệt là mụn sưng viêm.', 'Hướng dẫn sử dụng Chấm mun Juliette Armand Clarifying Stick Làm sạch da và lau khô.\r\nLấy mộ lượng Juliette Armand Clarifying Stick chấm lên các vị trí có mụn.', 'Thành phần và lưu ý Chấm mun Juliette Armand Clarifying Stick\r\nAxit azelaic 5,5%: Hoạt chất được ưu ái cao trong điều trị mụn bởi tính đa nhiệm mà không gây kích thích mạnh bạo. Acid Azelaic làm thông thoáng lỗ chân lông, xử lý các bít tắc cứng đầu khó chịu, lại đồng thời chống viêm ức chế vi khuẩn gây mụn.\r\nAxit salicylic 1,4%: Tinh chỉnh lỗ chân lông và giúp giảm sự hình thành của mụn trứng cá.\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nChiết xuất từ cây liễu Canada: Có chứa axit salicylic giúp trị mụn vì khả năng giúp da loại bỏ tế bào chết và làm thông thoáng lỗ chân lông; nó cũng có thể kích thích sự hình thành tế bào mới.\r\nChiết xuất Mimosa: Giảm tình trạng kích ứng, tinh dầu hoa này có đặc tính chống viêm hiệu quả do tỷ lệ azulene và bisabolol cao hơn. Bisabolol ngăn ngừa kích ứng và cung cấp hương hoa dịu nhẹ. Chống viêm, tái tạo, chống oxy hóa và điều trị kích ứng da hiệu quả.\r\nAlcohol denat: khi thoa lên da sẽ làm các mô sinh học trên da co hoặc kéo, các phân tử trong hợp chất này sẽ hoạt động và liên kết với protein keratin trong da thành một hàng rào bảo vệ da, làm mát da, săn chắc và giúp se khít lỗ chân lông cho da.\r\nSalicylic acid: giúp trị mụn, chống viêm và kiểm soát nhờn, kháng khuẩn, kháng viêm, làm sạch sâu, từ đó lỗ chân lông được thông thoáng khiến cho bụi bẩn và bã nhờn không còn đọng lại trên da và gây ra mụn.\r\n\r\nThành phần đầy đủ: Aqua, A-Bisabolol, Azelaic Acid, Ricinoleth-40, Sodium Hydroxide, Hydroxyethylcellulose, Hydrolyzed Milk Protein, Benzophenone-4, Bisabolol, Disodium Edta, Epilobium Angustifolium Flower/Leaf/Stem Extract, Mimosa Tenuiflora Bark Extract, Phenoxyethanol Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 1, 1000, '2023-12-08', '2024-02-08'),
(6, 'Cleansing Face Foam Juliette Armand Bọt Rửa Mặt', '6.jpg', '1050000', '945000', 'Juliette armand cleansing face foam Lợi ích Sữa rửa mặt Juliette Armand Cleansing Face Làm sạch bề mặt, dễ dàng làm sạch bụi bẩn, lớp trang điểm.\r\nLàm sạch sâu, loại bỏ dầu thừa cải thiện cấu trúc giúp làn da sáng, khỏe hơn.', 'Juliette armand cleansing face foam là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Sữa rửa mặt Juliette Armand Cleansing Face Với các phân tử dầu siêu nhỏ, gia tăng hoạt động làm sạch bề mặt, dễ dàng làm sạch bụi bẩn, lớp trang điểm. Chiết xuất dưa chuột làm sạch sâu, loại bỏ dầu thừa cải thiện cấu trúc giúp làn da sáng, khỏe hơn.\r\nBọt rửa mặt Juliette Armand Cleansing Face Foam chứa các thành phần làm sạch bề mặt dạng nhẹ giúp làm sạch bụi bẩn, loại bỏ chất thải dư thừa trên da, hấp thụ chất bã dư thừa và cân bằng dầu. Với công thức còn có chiết xuất liễu thảo mộc của Canada giúp ức chế hoạt động của vi khuẩn P.Acnes (vi khuẩn gây mụn) và chống viêm.\r\n\r\nDạng bọt có chứa các thành phần làm sạch sâu bụi bẩn, lớp trang điểm bám trên bề mặt da, hạn chế bít tắc lỗ chân lông và lên mụn, đồng thời tái sinh và làm săn chắc da mà không gây kích ứng và khô da.', 'Đối tượng Juliette armand cleansing face foam Đối tượng Sữa rửa mặt Juliette Armand Cleansing Face Dành cho mọi loại da', 'Hướng dẫn sử dụng Juliette armand cleansing face foam Hướng dẫn sử dụng Sữa rửa mặt Juliette Armand Cleansing Face Bơm bọt ra các đầu ngón tay mềm, thoa toàn mặt và massage xoay tròn nhẹ nhàng rồi rửa sạch lại bằng nước Juliette armand cleansing face foam ', 'Thành phần và lưu ý Sữa rửa mặt Juliette Armand Cleansing Face\r\nChất hoạt động bề mặt nhẹ: Chất hoạt động bề mặt dạng anion có tác dụng tạo bọt, làm sạch tốt. Bên cạnh đó, chất hoạt động bề mặt lưỡng tính góp phần làm dịu nhẹ cho làn da. Ngoài ra, Chất hoạt động bề mặt không ion và gốc axit amin được sử dụng phổ biến trong sữa rửa mặt để giúp công thức sản phẩm trở nên dịu nhẹ.\r\n\r\nChiết xuất dưa chuột: chứa đến 96% là nước, cùng với saponins và giàu các loại vitamin như: Vitamin C, vitamin A, vitamin B1, vitamin B2, vitamin B6, vitamin E, vitamin K,…\r\nBên cạnh đó, trong chiết xuất dưa leo cũng chứa hàm lượng lớn các khoáng chất như: Kali, lưu huỳnh,…đây là những chất có nhiều tác dụng tốt với làn da, nên được ứng dụng nhiều trong các sản phẩm chăm sóc cơ thể và mỹ phẩm làm đẹp.\r\nChiết xuất dưa leo có nhiều công dụng trong việc làm đẹp, trong số đó phải kể đến việc dưỡng ẩm cho da mềm mịn, phục hồi và làm mát làn da bị cháy nắng.\r\nLàm chậm quá trình lão hóa\r\nChiết xuất dưa leo cũng chứa thành phần lưu huỳnh, đây là chất có tác dụng làm sạch và thu nhỏ lỗ chân lông, ngăn quá trình lão hóa da, cho làn da tươi trẻ.\r\nDưa chuột chứa nhiều vitamin và chất dinh dưỡng giúp chúng có lợi thế khi chăm sóc da. Vitamin đóng một vai trò quan trọng đối với sức khỏe tổng thể nhưng chúng đặc biệt hiệu quả trong việc hỗ trợ sức khỏe làn da khi bôi tại chỗ.\r\n\r\nDưa chuột chứa nhiều chất chống oxy hóa, là các phân tử giúp chống lại các tổn thương do quá trình oxy hóa gây ra bởi các gốc tự do. Trái cây và rau quả nói chung rất giàu chất chống oxy hóa nhưng dưa chuột nói riêng chứa nhiều vitamin C, axit caffeic và axit folic. Vitamin C, thường được liên kết với các loại trái cây họ cam quýt như cam và bưởi, là một chất chống oxy hóa giúp làm sáng và làm sáng da. Axit caffeic và axit folic giúp tăng sản xuất collagen và chống lại các dấu hiệu lão hóa sớm. Sản xuất collagen thường giảm dần theo thời gian, đó là lý do tại sao bạn nên kết hợp các thành phần như axit caffeic và axit folic vào quy trình chăm sóc da hàng ngày của mình Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'DEFAULT', 1, 500, '2024-02-05', '2024-02-24'),
(7, 'Collagen Elastin Serum Juliette Armand Tinh Chất Tái Tạo Da', '7.jpg', '1050000', '945000', 'Lợi ích Serum Juliette Armand Collagen Elastin Hỗ trợ cho các tế bào da liên tục tái sinh và phục hồi.\r\n\r\nĐiều tiết toàn bộ các protein trong da.\r\n\r\nGiúp giữ ẩm và củng cố độ săn chắc.\r\n\r\nGia tăng đàn hồi và tế bào mới.\r\n\r\nCho hiệu ứng căng da, hạn chế các nếp nhăn sâu và chống chảy sệ.\r\n\r\nDành cho da thường, khô.', 'Serum Juliette Armand Collagen Elastin là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Tinh chất săn chắc da Juliette Armand Collagen Elastin Serum điều tiết toàn bộ các protein trong da, giúp giữ ẩm và củng cố độ săn chắc, gia tăng đàn hồi và tế bào mới.\r\nTừ tuổi 18-20 trở đi, mật độ và số lượng các sợi collagen – elastin hao hụt dần nên cấu trúc của nó không còn bền vững và chặt chẽ nữa. Biểu hiện rõ rệt nhất chính là da không còn rạng rỡ, căng bóng mà trở nên khô, nhăn và chảy sệ. Đó là lý do HER giới thiệu đến chị em Serum Armand Collagen Elastin giúp bổ sung lượng collagen để níu giữ tuổi xuân.\r\n\r\nTinh chất săn chắc da Juliette Armand Collagen Elastin Serum dành cho da thường, khô giúp điều tiết toàn bộ các protein trong da, giúp giữ ẩm và củng cố độ săn chắc, gia tăng đàn hồi và tế bào mới. Sản phẩm cho hiệu ứng căng da, hạn chế các nếp nhăn sâu và chống chảy sệ.\r\n\r\nMột loại huyết thanh với elastin thủy phân và collagen biển. Collagen và elastin tạo nên hầu hết các protein của da, chịu trách nhiệm về độ săn chắc và đàn hồi của nó, đồng thời giúp tái tạo và tái sinh tế bào của da. Quá trình sinh tổng hợp và chức năng của các sợi collagen và elastin giảm dần theo thời gian, dẫn đến các đường nhăn, nếp nhăn và sự thư giãn của da. Collagen Elastin củng cố các nguồn dự trữ collagen và elastin, nó giữ nước và tăng độ ẩm cho da.\r\nTinh chất săn chắc da Juliette Armand Collagen Elastin Serum dành cho da thường, khô, sản phẩm điều tiết toàn bộ các protein trong da, giúp giữ ẩm và củng cố độ săn chắc, gia tăng đàn hồi và tế bào mới. Sản phẩm cho hiệu ứng căng da, hạn chế các nếp nhăn sâu & chống chảy sệ.\r\n', 'Đối tượng Serum Juliette Armand Collagen Elastin Dành cho da thường, khô, sản phẩm điều tiết toàn bộ các protein trong da, giúp giữ ẩm và củng cố độ săn chắc, gia tăng đàn hồi và tế bào mới. Sản phẩm cho hiệu ứng căng da, hạn chế các nếp nhăn sâu & chống chảy sệ.', 'Hướng dẫn sử dụng Serum Juliette Armand Collagen Elastin Thoa 1 lượng nhỏ sản phẩm lên da và masage cho đến khi sản phẩm được hấp thu hết.', 'Thành phần và lưu ý Serum Juliette Armand Collagen Elastin\r\nCollagen 10%: Giúp giải thiện nhiều vấn đề của da đặc biệt loại bỏ các rãnh nhăn, nếp nhăn trên da. Vì công dụng collagen là thành phần chính của các mô liên kết nên giúp da trở nên căng mọng hơn, duy trì sự săn chắc, độ đàn hồi nhờ các mô liên kết và tăng sức khỏe của da.\r\nelastin 2%: Elastin khiến cấu trúc của mô da trở nên đàn hồi hơn, đồng thời nó cũng giúp ngăn ngừa tình trạng mất nước trên da. Đó là lý do bổ sung đầy đủ elastin làn da sẽ giữ được độ mịn màng, săn chắc. Vì elastin giúp củng cố cấu trúc mô da nên tạo được mạng lưới tế bào bền vững, tạo nên một bề mặt da căng bóng\r\nThành phần đầy đủ: Aqua, Glycerin, Butylene Glycol, Hydrolyzed Elastin, Cyclopentasiloxane, Collagen Thủy Phân, Phenoxyethanol, Cyclohexasiloxane, Glyceryl Polyacrylate, Ethylhexylglycerin, Caprylyl Glycol, Kali Sorbat, Glyceryl Acrylate / Acrylic Acid Copolymer, Pvm / Ma Copolymer Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 2, 100, '2023-11-08', '2023-12-08'),
(8, 'Exfoliating Enzyme Gel Juliette Armand Gel Tẩy Da Chết', '8.jpg', '1150000', '1035000', 'Juliette armand exfoliating enzyme gel Lợi ích Tẩy da chết Juliette Armand Exfoliating Enzyme Giảm bớt sự xuất hiện của các nếp nhăn\r\n\r\nLàm sạch sâu, tái sinh và tăng độ sáng cho da\r\n\r\nLàm dịu và giữ ẩm da\r\n\r\nThích hợp sử dụng cho cả làn da nhạy', 'Juliette armand exfoliating enzyme gel là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Tẩy da chết Juliette Armand Exfoliating Enzyme Gel tẩy da chết Juliette Armand Exfoliating Enzyme Gel từ enzym quả lê gai giúp gia tăng quá trình thay da tự nhiên thông qua việc phân giải protein thừa. Nhờ đó, giảm bớt sự xuất hiện của các nếp nhăn, làm sạch sâu, tái sinh và tăng độ sáng cho da. Lô hội và Ure làm dịu, giữ ẩm và làm tăng khả năng liên kết của nước trên da giúp khóa ẩm hiệu quả.\r\n\r\nExfoliating Enzyme Gel loại bỏ các tế bào chết của da mà không gây kích ứng và đồng thời phục hồi và làm sáng da. Nó kết hợp tác dụng tẩy tế bào chết bằng enzym của quả lê gai với khả năng dưỡng ẩm dịu nhẹ của lô hội và urê. Hoạt động enzym của lê gai giúp tăng cường quá trình lột da tự nhiên, tăng hoạt tính enzym tham gia vào quá trình ly giải protein mà không gây kích ứng. Nhờ đó làm giảm sự xuất hiện của đường nhăn và nếp nhăn, đồng thời cải thiện độ sáng của da. Thích hợp để sử dụng thường xuyên và cho da nhạy cảm và da thường.', 'Đối tượng Juliette armand exfoliating enzyme gel Đối tượng Tẩy da chết Juliette Armand Exfoliating Enzyme Gel tẩy da chết Juliette Armand Exfoliating Enzyme Gel là sản phẩm dành cho da nhạy cảm.', 'Hướng dẫn sử dụng Juliette armand exfoliating enzyme gel Hướng dẫn sử dụng Tẩy da chết Juliette Armand Exfoliating Enzyme Thoa 1 lượng sản phẩm vừa đủ lên da sạch, sau 10 phút, thoa serum hoặc kem lên gel.', 'Thành phần và lưu ý Tẩy da chết Juliette Armand Exfoliating Enzyme\r\nChiết xuất quả lê gai: Tác dụng làm trẻ hóa, nó giúp bảo vệ da khỏi tia nắng mặt trời, giúp ngăn ngừa sự xuất hiện của các đốm đồi mồi da trở nên đàn hồi hơn, trông tươi hơn.\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da.\r\nUrea: Đóng vai trò như một chất hút ẩm tương tự hyaluronic acid và glycerin. Nó sẽ hút độ ẩm từ bên ngoài môi trường vào da để giữ cho chúng luôn ngậm nước. Ngoài ra, urea còn giúp làm tăng khả năng liên kết của nước trên da giúp khóa ẩm hiệu quả.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nDimethicone: giữ cho tất cả các thành phần trong một sản phẩm không bị tách rời, đồng thời tạo một kết cấu có độ mịn và mượt cho sản phẩm. Khi thoa lên da hoặc tóc, dimethicone tạo ra một hàng rào vật lý giúp giữ ẩm cho da và hạn chế tình tình tóc khô xơ.\r\nPhenoxyethanol: được sử dụng như một chất bảo quản hoặc kháng khuẩn trong những loại mỹ phẩm khác để không làm hư hỏng hoặc mất tác dụng của sản phẩm. Giảm mụn trứng cá: Trong một số sản phẩm, phenoxyethanol kết hợp với hóa chất khác có tác dụng làm giảm đáng kể mụn trứng cá.\r\n\r\nThành phần đầy đủ: Aqua, Urea, Aloe Barbadensis Leaf Extract, Sodium Polyacrylate, Hydrogenated Polydecene, Ppg-26-Buteth-26, Peg-40 Hydrogenated Castor Oil, Ethylhexylglycerin, Caprylyl Glycol, Hydrolyzed Opuntia Ficus-Indica Flower Extract, Trideceth-6 Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 0, 100, '2023-12-08', '2024-01-08'),
(9, 'Face Gel SPF30 Juliette Armand Gel Chống Nắng Tạo Màng', '9.jpg', '1380000', '1242000', 'Lợi ích Juliette armand sunfilm face gel spf 30 Lợi ích Kem chống nắng Juliette Armand Sunfilm SPF 30 Bảo vệ da khỏi các bức bức xạ UVA, UVB, hồng ngoại (IR).\r\nChống gốc tự do oxy hóa, lão hóa da do ánh nắng.\r\nGiúp ngăn ngừa tổn thương oxy hóa và thúc đẩy quá trình tái tạo tự nhiên của da.\r\nLàm dịu và khỏe da.', 'Juliette armand sunfilm face gel spf 30 là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem chống nắng Juliette Armand Sunfilm SPF 30 Gel tạo màng chống nắng Juliette Armand Sunfilm Face Gel SPF30 không trôi, có tính chống oxy hóa mạnh dành cho mọi loại da, giúp bảo vệ da khỏi các bức bức xạ UVA, UVB, hồng ngoại (IR), chống gốc tự do oxy hóa, lão hóa da do ánh nắng, đồng thời làm dịu và khỏe da.\r\nGel tạo màng chống nắng Juliette Armand Sunfilm Face Gel SPF30 không chứa dầu, không trôi, có tính chống oxy hóa mạnh dành cho mọi loại da, giúp bảo vệ da khỏi các bức bức xạ UVA, UVB, hồng ngoại (IR), chống gốc tự do oxy hóa, lão hóa da do ánh nắng, đồng thời làm dịu và khỏe da. Sản phẩm giàu các thành phần làm dịu và chất chống oxy hóa đặc biệt, làm giảm kích ứng da và bảo vệ da khỏi bảo vệ da khỏi sự mất cân bằng oxy hóa và lão hóa do ánh nắng.\r\n\r\nSunfilm SPF30 Facial Gel là sản phẩm chống tia UV nhẹ nhàng với kết cấu tinh tế, nhanh chóng được hấp thụ trên da và không gây cảm giác nhờn. Rất thích hợp cho da nhạy cảm, da dầu ngoài ra còn có thể sử dụng với mọi loại da.', 'Đối tượng Juliette armand sunfilm face gel spf 30 Đối tượng Kem chống nắng Juliette Armand Sunfilm SPF 30 Sunfilm SPF30 Facial Gel là sản phẩm chống tia UV nhẹ nhàng với kết cấu tinh tế, nhanh chóng được hấp thụ trên da và không gây cảm giác nhờn. Rất thích hợp cho da nhạy cảm, da dầu ngoài ra còn có thể sử dụng với mọi loại da.', 'Hướng dẫn sử dụng Juliette armand sunfilm face gel spf 30 Hướng dẫn sử dụng Kem chống nắng Juliette Armand Sunfilm SPF 30 Thoa lượng đủ dày lên da 15’ trước khi ra nắng. Tùy vào thời gian hoạt động dưới ánh nắng để thoa lại sản phẩm.', 'Lô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da.\r\nPanthenol: Giúp dưỡng ẩm và làm mịn da và tóc của bạn từ bên trong ở dạng ăn được và từ bên ngoài ở dạng bôi ngoài da. Panthenol là một chất hóa học được tạo ra từ axit pantothenic, còn được gọi là vitamin B5. Nó có nguồn gốc hữu cơ và cũng có thể được sản xuất từ cả nguồn thực vật và động vật. Làm dịu các tổn thương, giảm kích ứng, củng cố lớp màng lipid, duy trì độ đàn hồi cho da\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nDimethicone: giữ cho tất cả các thành phần trong một sản phẩm không bị tách rời, đồng thời tạo một kết cấu có độ mịn và mượt cho sản phẩm. Khi thoa lên da hoặc tóc, dimethicone tạo ra một hàng rào vật lý giúp giữ ẩm cho da và hạn chế tình tình tóc khô xơ.\r\nPhenoxyethanol: được sử dụng như một chất bảo quản hoặc kháng khuẩn trong những loại mỹ phẩm khác để không làm hư hỏng hoặc mất tác dụng của sản phẩm. Giảm mụn trứng cá: Trong một số sản phẩm, phenoxyethanol kết hợp với hóa chất khác có tác dụng làm giảm đáng kể mụn trứng cá.\r\n\r\nThành phần chính: EUK-134, Venuceane, Helioguard, Antaron, Panthenol, Aloe Vera, Tinosorb S, Octocrylene, Octinoxate, Tinosorb M, TiΟ2, ZnΟ2\r\nThành phần đầy đủ: Aqua, Methylene Bis-Benzotriazolyl Tetramethylbutylphenol (Nano), Aloe Barbadensis Leaf Extract, Ethylhexyl Methoxycinnamate, Octocrylene, Butylene Glycol, Dimethicone, Polyacrylamide , Panthenol, C13-14 Isoparaffin, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Vp/Eicosene Copolymer, Thermus Thermophillus Ferment, C12-15 Alkyl Benzoate, Decyl Glucoside, Phenoxyethanol, Parfum, Polysorbate 20, Zinc Oxide (Nano), Titanium Dioxide (Nano), Citric Acid, Ethylhexylglycerin, Caprylyl Glycol, Glycerin, Laureth-7, Ci 77492, Alumina, Polyhydroxystearic Acid, Ci 77491, Alcohol, Methicone, Xanthan Gum, Triethoxycaprylylsilane, Ci 77499, Lecithin, Porphyra Umbilicalis Extract, Ethylbisiminomethylguaiacol Ma', 'HOT', 1, 100, '2022-12-08', '2024-12-18'),
(10, 'Gel Phục Hồi Juliette Armand Rejuvenating', '10.jpg', '1990000', '1791000', 'Lợi ích Gel phục hồi Juliette Armand Rejuvenating Sản phẩm làm mờ sẹo, vết thâm và tái tạo da. Giúp dưỡng ẩm và làm dịu da, cải thiện bề mặt da, cho da mịn mượt và đều màu. Được khuyên dùng sau các trị liệu lột tẩy hóa học. Sản phẩm ứng dụng công nghệ siêu dẫn bảo toàn hoạt chất kích hoạt nhanh tế bào.', 'Gel phục hồi Juliette Armand Rejuvenating là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Gel dưỡng ẩm và làm dịu da, cải thiện bề mặt da, cho da mịn mượt và đều màu.\r\nGel phục hồi tái tạo da Juliette Armand Rejuvenating Gel làm mờ sẹo, vết thâm và tái tạo da. Giúp dưỡng ẩm và làm dịu da, cải thiện bề mặt da, cho da mịn mượt và đều màu. Em gel phục hồi này của nhà Juliette Armand được ứng dụng công nghệ siêu dẫn bảo toàn hoạt chất kích hoạt nhanh tế bào để tái tạo và điều chỉnh cấu trúc da bị lão hóa hoặc bị tổn thương. Gel này củng cố các chức năng tự nhiên và bảo vệ của da, hydrat hóa da và cải thiện độ đàn hồi của da.\r\n\r\nĐây cũng là loại gel lý tưởng để chăm sóc đặc biệt sau khi điều trị chống lão hóa nhờ các yếu tố sửa chữa, phục hồi. Nó được sử dụng cho các tình trạng da khô và để giảm nếp nhăn, sự đổi màu da và sửa chữa các vết thương trên da.', 'Đối tượng Gel phục hồi Juliette Armand Rejuvenating Juliette Armand Rejuvenating Gel là sản phẩm phục hồi da lý tưởng cho các làn da đang gặp vấn đề:\r\n\r\nDa sau các liệu trình trẻ hoá bằng vi tảo hoặc peel axit, sau laser.\r\nDa sau điều trị mụn cần hoàn thiện nền da và làm sáng thâm mụn.\r\nDa dầu cần dưỡng và tái sinh làm sáng mượt, đều màu.', 'Hướng dẫn sử dụng Gel phục hồi Juliette Armand Rejuvenating Làm sạch da bằng tẩy trang và sữa rửa mặt.\r\nDùng Toner để cân bằng da.\r\nLấy lượng Juliette Armand Rejuvenating Gel vừa đủ thoa đều toàn mặt và mát xa nhẹ nhàng.', 'Kelifluo: Tạo lớp màng bảo vệ da trong điều kiện thời tiết khắc nghiệt và ô nhiễm, làm dịu, sửa chữa các tổn thương\r\nPanthenol: Được gọi là “vị cứu tinh” của làn da bị hư tổn, da đang bị tổn thương ha da nhạy cảm. Panthenol là một hợp chất hóa học tự nhiên có mối liên hệ chặt chẽ với vitamin B5. Hay dễ hiểu hơn nó là chất dẫn xuất hòa tan của Provitamin B5, đó là acid pantothenic.\r\nDrieline: Men (beta-glucan) tăng đề kháng, củng cố hệ thống phòng vệ của da, giảm đỏ, thúc đẩy quá trình tải sinh và phục hỏi, tổng hợp Collagen\r\nDemonectin: Cấp nước, củng cố mô liên kết, chữa lành tổn thương, giảm nhăn\r\nPentavitin: Siêu dưỡng ẩm sâu (giữ tới 72h), chống stress, giảm kích ứng sau peel, giảm khô bong bề mặt, gia tăng hàng rào bảo vệ da.\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định\r\nPanthenol: Giúp dưỡng ẩm và làm mịn da và tóc của bạn từ bên trong ở dạng ăn được và từ bên ngoài ở dạng bôi ngoài da. Panthenol là một chất hóa học được tạo ra từ axit pantothenic, còn được gọi là vitamin B5. Nó có nguồn gốc hữu cơ và cũng có thể được sản xuất từ cả nguồn thực vật và động vật. Làm dịu các tổn thương, giảm kích ứng, củng cố lớp màng lipid, duy trì độ đàn hồi cho da\r\nPhenoxyethanol: được sử dụng như một chất bảo quản hoặc kháng khuẩn trong những loại mỹ phẩm khác để không làm hư hỏng hoặc mất tác dụng của sản phẩm. Giảm mụn trứng cá: Trong một số sản phẩm, phenoxyethanol kết hợp với hóa chất khác có tác dụng làm giảm đáng kể mụn trứng cá.\r\n\r\nThành phần khác: Aqua, Glycerin, Saccharide Isomerate, Polysorbate 20, Ppg-26-Buteth-26, Polyperfluoromethylisopropyl Ether, Hydrogenated Starch Hydrolysate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Phenoxyethanol, Peg-40 Hydrogenated Castor Oil, Panthenol, Caprylyl Glycol, Ethylhexylglycerin, Potassium Hydroxide, Oligopeptide-5, Disodium Edta, Parfum, Citric Acid, Sodium Citrate, Faex Extract, Sodium Phosphate, Tea-Lauryl Sulfate Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 0, 100, '2020-12-03', '2023-02-08'),
(11, 'Gel Rửa Tay Juliette Armand Cleansing Hand', '11.jpg', '1950000', '1670000', 'Gel rửa tay Juliette Armand Cleansing Hand Lợi ích Gel rửa tay Juliette Armand Cleansing Hand Cân bằng độ ẩm và nuôi dưỡng bảo vệ làn da mạnh mẽ\r\nChống khô, giữ ẩm và tái tạo làn da, giúp da mềm mại và mịn màng.', 'Gel rửa tay Juliette Armand Cleansing Hand là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Gel rửa tay Juliette Armand Cleansing đến từ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam.Gel rửa tay dưỡng ẩm Juliette Armand Cleansing Hand Gel giữ ẩm và bảo vệ da tay với 70% cồn etylic và axit hyaluronic. Nó mang lại cảm giác mềm mại và dễ chịu trên da. Gel rửa tay là một thứ vô cùng cần thiết giữa thời tiết se lạnh như thế này, nó sẽ giúp da tay được dưỡng ẩm, mịn màng đem lại một làn da không bong tróc, mềm mại', 'Đối tượng Gel rửa tay Juliette Armand Cleansing Phù hợp cho mọi loại da, đặc biệt da khô ráp, da tay sần sùi', 'Làm ướt tay, sau đó cho một lượng vừa đủ gel rửa tay lên và xoa đều. Sau đó rửa lại bằng nước sạch', 'Alcohol denat, aqua, butylene glycol, peg-8, triethanolamin,… Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 0, 100, '2019-12-04', '2024-12-10'),
(12, 'Hyaluron Gel Wellmaxx Minisize', '12.jpg', '290000', '290000', 'Khả năng cấp ẩm gấp 2 lần\r\nTăng độ đàn hồi, săn chắc tự nhiên của làn da\r\nLàm dịu da cấp tốc, giảm ngay biểu hiện bong tróc, nứt nẻ trên da\r\nTăng cường cấp ẩm đa tầng, tạo hiệu ứng căng bóng cho da.\r\nKích thích tăng sinh collagen, da phục hồi sức khỏe săn chắc hơn.', 'Da khô thường xuất hiện các biểu hiện như khô ráp, bong tróc hoặc xỉn màu. Tuy nhiên, việc chăm sóc da khô lại dễ dàng hơn so với da dầu, bạn chỉ cần cấp ẩm cấp nước đúng liều lượng thì tình trạng này có thể cải thiện. Gel dưỡng ẩm cho da khô Wellmaxx Hyaluron Moist Intense Gel Concentrate làm “điêu đứng” mọi phái đẹp. Sản phẩm với nồng độ Axit Hyaluronic tối đa cùng các chất tăng cường độ ẩm. Đặc biệt không chứa hương liệu, là sản phẩm lý tưởng cho sứ mệnh chăm sóc chuyên sâu hàng ngày – ngay cả khi chăm sóc ban ngày hay ban đêm. Sau thời gian kiên trì sử dụng, da của bạn trông săn chắc hơn, đàn hồi hơn và tươi trẻ hơn.', 'Axit Hyaluronic: Cung cấp độ ẩm tối đa cho da với khả năng giữ nước gấp 1000 lần sản phẩm dưỡng ẩm thông thường. Giúp da mềm mịn và căng bóng mỗi ngày.\r\nD – Panthenol: Tái tạo và phục hồi hàng rào bảo vệ da. Chữa lành các tế bào bị tổn thương và tăng sinh collagen giúp da săn chắc, mịn màng và căng khỏe.\r\nHydrosystem Aquaxyl: Tăng độ ẩm ở lớp ngoài cùng ngay lập tức, cải thiện tình trạng khô ráp, nứt nẻ, cải thiện chỉ sau 1 tháng sử dụng.', 'Phù hợp với mọi loại da, đặc biệt là làn da khô, thiếu ẩm, bong tróc, nứt nẻ\r\nDa xuất hiện các dấu hiệu lão hóa như nếp nhăn, vết chân chim, khô ráp, da xỉn màu…\r\nNhững ai đang tìm kiếm giải pháp chăm sóc da tiện lợi, phù hợp cho cả ngày đêm', 'Sau bước làm sạch và cân bằng da, lấy một lượng Gel dưỡng ẩm vừa đủ chấm lên 5 vùng chính trên gương mặt (trán, cằm, mũi và 2 má). Dùng tay thoa đều toàn mặt, kết hợp massage nhẹ nhàng cho Gel dưỡng thẩm thấu vào da. Khi dùng vào buổi sáng, bạn nên kết hợp kem chống nắng để bảo vệ làn da tốt nhất.', 'Hiệu quả có thể khác nhau tùy theo cơ địa của người dùng\r\nSản phẩm của Wellmaxx là được mỹ phẩm, cần tham vấn ý kiến chuyên gia trước khi dùng\r\nTránh tiếp xúc trực tiếp với ánh nắng mặt trời, bảo quản nơi khô ráo thoáng mát\r\nTránh xa tầm tay của trẻ em\r\nQuy cách sản phẩm\r\n\r\nTên sản phẩm: Hyaluron Moist Intense Gel Concentrate\r\nThương hiệu: Wellmaxx\r\nXuất xứ: Đức\r\nDung tích: 10ml/chai (mini size)', 'DEFAULT', 0, 100, '2023-12-18', '2024-02-23'),
(13, 'Juliette Armand Aloe Vera Serum', '13.jpg', '1050000', '945000', 'Lợi ích Serum Juliette Armand Aloe Vera Giữ ẩm và làm dịu da khỏi kích ứng và viêm sưng.\r\nPhục hồi da tổn thương do xâm lấn, kích ứng.\r\nTái cấu trúc tế bào và phục hồi tổn thương da.\r\nGiảm mụn và làm sáng da, giúp làm đầy nếp nhăn và chống lão hóa.', 'Juliette armand aloe vera serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Tinh chất lô hội dưỡng ẩm dịu da Juliette Armand Aloe Vera Serum đậm đặc chiết xuất lô hội xanh có tác dụng giữ ẩm và làm dịu da khỏi kích ứng và viêm sưng. Lô hội là một hỗn hợp tự nhiên tuyệt vời chứa vitamin C và E, các loại enzyme, axit amin và hơn 200 chất có lợi khác góp phần tái cấu trúc tế bào và phục hồi tổn thương da. Sản phẩm được khuyên dùng cho da nhạy cảm và bị kích ứng.\r\nCông dụng chính của tinh chất dưỡng ẩm Aloe Vera Serum Juliette Armand Sản phẩm ra đời dựa trên quá trình nghiên cứu của đội ngũ chuyên gia hàng đầu của Juliette Armand. Với những công dụng tuyệt vời, hẳn chị em sẽ không thất vọng khi sử dụng tinh chất Aloe Vera Serum Juliette Armand . – Chiết xuất từ cây lô hội mang đến làn da khả năng giữ ẩm hiệu quả cho da. Đồng thời hoạt chất này cũng giúp tác động vào sâu trong cấu trúc da, nâng cao khả năng chống kích ứng cũng như hạn chế hiện tượng viêm, sưng da. – Điều trị các tổn thương do kích ứng hay các tình trạng xâm lấn của da tích cực, giúp kháng khuẩn, kháng viêm. – Cải thiện quá trình tái tạo da, phục hồi nhanh chóng trên các vùng da bị tổn thương. Từ đó giúp mang lại cho người sử dụng làn da căng mịn đầy sức sống. – Giảm mụn, làm sáng da và chống lão hóa da tích cực. Bên cạnh đó, dòng mỹ phẩm là một trong những biện pháp giảm nếp nhăn hiệu quả trên da, giúp da căng tràn sức sống, tươi trẻ.', 'Juliette Armand Aloe Vera Serum có thành phần an toàn và lành tính phù hợp với mọi loại da, đặc biệt là các làn da:\r\n\r\nDa nhạy cảm, dễ kích ứng.\r\nDa đang có mụn viêm sưng.\r\nDa ửng đỏ do bắt nắng.\r\nDa thiếu độ ẩm.', 'Hướng dẫn sử dụng Serum Juliette Armand Aloe Vera Làm sạch da với tẩy trang và sữa rửa mặt.\r\nDùng toner để cân bằng da.\r\nThoa 1 lượng nhỏ Juliette Armand Aloe Vera Serum lên da và masage cho đến khi sản phẩm được hấp thu hết.\r\nSử dụng kem dưỡng để đạt được kết quả tốt nhất.\r\nKhi sử dụng buổi sáng nên kết hợp kem chống nắng để bảo vệ da.\r\nSử dụng ngày 2 lần sáng và tối.', 'Aloe Barbadensis Leaf Extract, Aloe Vera 30%, Aqua, Butylene Glycol, Caprylyl Glycol, CI 19140, CI 42051, CI 42090, Ethylhexylglycerin, Glycerin, Glyceryl Acrylate/Acrylic Acid Copolymer, Glyceryl Polyacrylate, PEG-40 Hydrogenated Castor Oil, phenoxyethanol, Potassium Sorbate, PPG-26-Buteth-26, PVM/MA COPOLYMER\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 0, 100, '2022-12-08', '2023-02-27');
INSERT INTO `products` (`idProduct`, `name`, `image`, `costPrice`, `sellingPrice`, `benifit`, `descride`, `introduce`, `object`, `instruct`, `note`, `tag`, `sellNumber`, `qttStock`, `createdAt`, `updatedAt`) VALUES
(14, 'Juliette Armand Calming Bliss', '14.jpg', '680000', '612000', 'Lợi ích jJuliette armand calming bliss Hỗ trợ khả năng kháng viêm cho da.\r\nGiúp tăng cường khả năng dưỡng ẩm đồng thời sửa chữa những tổn thương trên da.\r\n\r\nGiúp làn da trở nên mềm mượt và tràn đầy sức sống.\r\n\r\nHiệu quả sử dụng cho làn da sau khi trị liệu xâm lấn, sau laser hoặc trải qua các hình thức lột tẩy khác.', 'Juliette armand calming bliss là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand Calming Bliss đến từ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam.Armand Calming Bliss giúp kháng viêm, dưỡng ẩm và sửa chữa các tổn thương, đem lại sự mượt mà tuyệt vời cho làn da.\r\nCalming Bliss là sản phẩm được thiết kế đặc biệt để làm dịu da bị kích ứng mạnh, mang lại một làn da khoẻ mạnh và mượt mà. Nó chứa Allantoin là một thành phần có tác dụng dưỡng ẩm và sửa chữa các tổn thương. Βisabolol là một dẫn xuất từ ​​hoa cúc có tác dụng làm dịu và chống viêm. Panthenol được chuyển đổi thành axit pantothenic (vitamin B5) trong quá trình tiếp xúc với da, giúp hydrat hóa các mô và góp phần chữa lành vết thương, kích thích tái tạo biểu mô và có đặc tính chống viêm.\r\n\r\nNgoài ra kem còn chứa nha đam là một loại cocktail tự nhiên bao gồm các vitamin, enzym, axit amin và các chất khác giúp hydrat hóa và giúp giảm kích ứng và làm ấm da. Chiết xuất Centella là một thành phần được sử dụng để tái tạo và chống sưng tấy. Công thức đặc biệt sử dụng sau các liệu trình xâm lấn hoặc sau laser. Calming Bliss là sản phẩm được thiết kế đặc biệt để làm dịu da bị kích ứng mạnh, mang lại một làn da khoẻ mạnh và mượt mà. Nó chứa Allantoin là một thành phần có tác dụng dưỡng ẩm và sửa chữa các tổn thương. Βisabolol là một dẫn xuất từ ​​hoa cúc có tác dụng làm dịu và chống viêm. Panthenol được chuyển đổi thành axit pantothenic (vitamin B5) trong quá trình tiếp xúc với da, giúp hydrat hóa các mô và góp phần chữa lành vết thương, kích thích tái tạo biểu mô và có đặc tính chống viêm.\r\n– Ngoài ra kem còn chứa nha đam là một loại cocktail tự nhiên bao gồm các vitamin, enzym, axit amin và các chất khác giúp hydrat hóa và giúp giảm kích ứng và làm ấm da. Chiết xuất Centella là một thành phần được sử dụng để tái tạo và chống sưng tấy. Công thức đặc biệt sử dụng sau các liệu trình xâm lấn hoặc sau laser.', 'Đối tượng jJuliette armand calming bliss Đối tượng Kem mặt Juliette Armand Calming Bliss Juliette Armand Calming Bliss là dòng kem dưỡng phục hồi an toàn và lành tính, thích hợp sử dụng với những trường hợp:\r\n\r\nLàn da sau trị liệu xâm lấn.\r\nLàn da trải qua quá trình laser hoặc các hình thức lột tẩy khác.', 'Hướng dẫn sử dụng jJuliette armand calming bliss Làm sạch da và lau khô mặt.\r\nThoa Juliette Armand Calming Bliss lên vùng da bị kích ứng, tổn thương và massage nhẹ cho sản phẩm thẩm thấu.\r\nChỉ dùng ngoài da.', 'Thành phần chi tiết\r\n\r\n– Bisabolol: Chất thực vật với thành phần hoạt tính azulene có nguồn gốc từ hoa cúc và có tác dụng làm dịu, chống viêm và làm mềm da mạnh mẽ\r\n\r\n– Panthenol: Một loại vitamin phức hợp vitamin B có tác dụng chữa bệnh, dưỡng ẩm và làm dịu da chống lại các chứng viêm và kích ứng.\r\n\r\n– Lô Hội: Cocktail tự nhiên chứa vitamin C và E, các enzym, axit amin và hơn 200 chất có lợi khác. Nó hydrat hóa và giúp giảm kích ứng da và cảm giác bỏng rát.\r\n\r\n– Centella Extract: Thúc đẩy tổng hợp collagen bằng cách góp phần làm săn chắc mô, tác nhân tái tạo mạnh và chống phù nề.\r\n\r\n– Methyl Salicylate: Là một este hữu cơ được sản xuất tự nhiên bởi kem đông y và được sử dụng như một chất chống dẻo. Nó làm dịu và sửa chữa làn da sau khi sử dụng, để lại nó cực kỳ mịn màng.\r\n\r\nThành phần đầy đủ: Aqua, Butylene Glycol, Aloe Barbadensis Leaf Extract, C12-20 Acid Peg-8 Ester, Glyceryl Stearate, Polyisoprene, Peg-100 Stearate, Triticum Vulgare Germ Oil, Panthenol, Glyceryl Stearate, Polyisoprene, Peg-100 Stearate , Allantoin, Dimethicone, Ethylhexylglycerin, Hydrogenated Polydecene, Centella Asiatica Leaf Extract, Methyl Salicylate, Peg-8, Trideceth-6, Tocopherol, Sodium Axit Benedin, Tai Dân Tndn, Sodium Benzidate Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'DEFAULT', 0, 100, '2022-12-02', '2024-12-06'),
(15, 'Juliette Armand Caviar Cream', '15.jpg', '1990000', '1791000', 'Lợi ích Juliette armand caviar cream Lợi ích Kem mặt Juliette Armand Caviar Omega 3&6 Bảo vệ tính toàn vẹn của tế bào.\r\nĐẩy nhanh quá trình sản xuất collagen tự nhiên của da giúp xóa mờ nếp nhăn, các dấu hiệu mệt mỏi\r\nNuôi dưỡng và cải thiện bề mặt da, cho làn da tươi mới, săn chắc, bóng khoẻ và mượt mà.', 'Juliette armand caviar cream là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand Caviar Omega 3&6 Kem trứng cá tầm Juliette Armand Caviar Omega 3&6 Cream tăng cường axit béo Omega-3, Omega-6 giúp nuôi dưỡng và cải thiện sự xuất hiện của làn da với các nếp nhăn và dấu hiệu mệt mỏi, mang lại làn da săn chắc và tươi mới.\r\ninh chất trứng cá tầm Double Caviar Ω3-Ω6 Serum giúp nuôi dưỡng và cải thiện sự xuất hiện của làn da với các nếp nhăn và dấu hiệu mệt mỏi, mang lại làn da săn chắc và tươi mới. Huyết thanh trứng cá muối đen và đỏ, giàu axit béo omega 3 và omega 6, vitamin, protein, axit amin và các nguyên tố vi lượng, cung cấp cho da các thành phần cần thiết để duy trì tính toàn vẹn của tế bào và đẩy nhanh quá trình sản xuất collagen tự nhiên.\r\n\r\nĐược làm giàu với Omega Oil, ocopherols, phytosterol và flavonoid, kết hợp với vitamin F và E, nó cải thiện chức năng hàng rào của da và bảo vệ màng tế bào bằng cách ngăn ngừa tổn thương DNA. Ngoài ra, nó còn chứa Evening Primrose, một loại dầu giàu axit béo không bão hòa đa để tạo thành một lớp màng bảo vệ cho làn da mệt mỏi. Da được tái tạo, các nếp nhăn được làm mịn và khuôn mặt lấy lại độ săn chắc.', 'Đối tượng Juliette armand caviar cream Đối tượng Kem mặt Juliette Armand Caviar Omega 3&6 Juliette Armand Caviar Omega 3-6 Cream là dòng kem dưỡng hoàn hảo cho các làn da đang gặp vấn đề:\r\n\r\nDa thiếu sức sống, mệt mỏi.\r\nDa có các dấu hiệu lão hóa, xuất hiện nếp nhăn.\r\n\r\n', 'Hướng dẫn sử dụng Juliette armand caviar cream Hướng dẫn sử dụng Kem mặt Juliette Armand Caviar Omega 3&6 Làm sạch da bằng tẩy trang và sữa rửa mặt.\r\nDùng Toner để cân bằng da.\r\nThoa Juliette Armand Caviar Omega 3-6 Cream lên toàn mặt và massage cho đến khi thẩm thấu hết.\r\nCó thể kết hợp Juliette Armand Double Caviar 3-6 Serum để đạt được kết quả tốt nhất.', 'Thành phần và lưu ý Kem mặt Juliette Armand Caviar Omega 3&6\r\nTrứng cá đen: có tác dụng làm đẹp da, Vitamin C trong trứng cá muối có tác dụng hỗ trợ sản xuất collagen, chất không thể thiếu để duy trì một làn da tươi trẻ. Đồng thời ngăn ngừa các vết nám, tàn nhang, giúp làn da căng bóng, sáng khỏe và trẻ trung. Vitamin B2 trong trứng cá muối còn có tác dụng ngăn ngừa mụn trứng cá ở tuổi trưởng thành.\r\nTrứng cá muối: trứng cá muối Caviar còn mang lại hiệu quả làm đẹp rất khả quan, bao gồm: tái sinh và kích thích Collagen, duy trì thanh xuân, đẩy lùi các dấu hiệu lão hóa, duy trì ẩm, tăng sức đề kháng, nâng tông và làm sáng da.\r\nVitamin F: mang lại cho da của chúng ta đó chính là chống lão hóa da, bảo vệ da, cung cấp dưỡng chất và giữ nước giúp bảo vệ làn da khỏi các tác nhân gây hại từ môi trường, vitamin F còn giúp xoa dịu làn da, giảm những tổn thương do mụn gây ra. Ngoài ra chúng còn có thể tránh những tác động do tia UV và ô nhiễm môi trường.\r\nVitamin E: giúp chống lại tác hại của gốc tự do đồng thời ngăn chặn tác động của tia UV đối với da. Vitamin E là một hợp chất chống viêm, giúp ngừa sưng, giảm phù nề da, Ngăn chặn tình trạng phát ban và nhiều biểu hiện khác do viêm da mãn tính gây ra. Vitamin E mang đến cho da sự mịn màng, đàn hồi, khoẻ đẹp, tươi trẻ.\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da.\r\n\r\nDầu INCA Omega (Ω3, Ω6, Ω9, Tocopherol).\r\n\r\nDầu hoa anh thảo.\r\n\r\nThành phần đầy đủ: Cyclopentasiloxane, Aqua, Ethylhexyl Palmitate, Butylene Glycol, Glycerin, Aloe Barbadensis Leaf Extract, Plukenetia Volubilis Seed Oil, Linoleic Acid, Oenothera Biennis Oil, Parfum, Sodium Chloride, Tocopheryl Acetate, Cocos Nucifera Oil, Sodium Levulinate, Sodium Anisate, Salmo Ovum Extract, Benzalkonium Chloride , Caviar Extract, Citric Acid, Linolenic Acid, Sodium Benzoate, Potassium Sorbate, Phenoxyethanol, Dipotassium Phosphate, Ci 19140, Sodium Dehydroacetate, Sorbic Acid, Undecylenic Acid, Ci 16185, Sodium Sulfate Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn d', 'NEW', 0, 100, '2022-12-14', '2023-12-08'),
(16, 'Juliette Armand Clarifying Active Cream', '16.jpg', '1150000', '1035000', 'Lợi ích Juliette armand clarifying active cream Lợi ích Kem mụn Juliette Armand Clarifying Active Ức chế hoạt động của vi khuẩn P.Acnes (vi khuẩn gây mụn)\r\nKháng khuẩn và chống viêm\r\nĐiều trị các triệu chứng của mụn trứng cá\r\nHấp thụ bã nhờn dư thừa\r\nCải thiện bề mặt da mà không gây khô và kích ứng.', 'Juliette armand clarifying active cream là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mụn Juliette Armand Clarifying Active Kem đặc trị mụn Juliette Armand Clarifying Active Cream giúp điều trị các triệu chứng của mụn trứng cá, hấp thụ bã nhờn dư thừa và cải thiện bề mặt da mà không gây khô và kích ứng.\r\nKem đặc trị mụn Juliette Armand Clarifying Active Cream chứa chiết xuất cây liễu thảo mộc Canada là thành phần ức chế hoạt động của vi khuẩn P.Acnes (vi khuẩn gây mụn), Azelaic, dầu hoa Manuka kháng khuẩn và chống viêm. Kem được thiết kế đặc biệt để làm giảm sự xuất hiện của các triệu chứng mụn trứng cá và nó hấp thụ bã nhờn dư thừa của da mà không gây khô và kích ứng.\r\n\r\nClarifying Active Cream một loại kem đặc trị với đa chức năng chứa các thành phần Sebopessina và Normaseb mà nó chứa trực tiếp làm giảm và điều chỉnh sự tiết bã nhờn và tiết dầu trên da mà không gây khô da. Sự kết hợp của Axit Azelaic với các thành phần Dầu Manuka và Dầu Jojoba giúp kem có đặc tính kháng khuẩn và chống viêm mạnh mẽ. Ngoài ra nó còn chứa chiết xuất lô hội, A-bisabolol và Panthenol, làm dịu làn da bị kích ứng, dễ nổi mụn đồng thời giữ độ ẩm cao, trong khi Polytrap hấp thụ dầu thừa để lại làn da mịn màng và căng bóng.', 'Đối tượng Juliette armand clarifying active cream Đối tượng Kem mụn Juliette Armand Clarifying Active Juliette Armand Clarifying Active Cream có thành phần từ tự nhiên nên khả năng an toàn và phù hợp với những làn da mụn, đặc biệt là làn da nhạy cảm bị mụn,thích hợp cho những đối tượng:\r\n\r\nĐang gặp tình trạng mụn trứng cá, mụn đầu đen hay các vết mụn thâm trên da,…\r\nCó làn da nhạy cảm, dễ bị kích ứng.\r\nCó làn da dầu cần được điều tiết lượng bã nhờn trên da để không làm bít tắc lỗ chân lông.', 'Hướng dẫn sử dụng Juliette armand clarifying active cream Hướng dẫn sử dụng Kem mụn Juliette Armand Clarifying Active Làm sạch da và lau khô mặt.\r\nSử dụng sản phẩm Juliette Armand Clarifying Active Cream với một lượng vừa đủ, bôi lên các vùng da bị mụn.\r\nMassage nhẹ nhàng từ 10 đến 20 giây theo hình xoắn ốc từ ngoài vào trong để các dưỡng chất thấm đều và tinh chất đi sâu vào tế bào da, giải quyết các loại vi khuẩn gây nên mụn.\r\nKết hợp với các loại kem dưỡng ẩm chăm sóc da.', 'Thành phần và lưu ý Kem mụn Juliette Armand Clarifying Active\r\nCanadian Willowherb: Một chất có trong tất cả các sản phẩm của dòng này. Điều này có tác dụng kháng khuẩn, tăng khả năng miễn dịch và mang lại tác dụng phục hồi và làm sáng tỏ khuôn mặt khó khăn.\r\nAllantoin: Giúp lớp da chết nhanh bong ra, đồng thời giúp da giữ nước nhiều hơn, làm tăng lượng nước trong tế bào, da sẽ mềm mại và mịn màng hơn.\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn. Chống viêm, làm dịu da: Ở phần gel của cây lô hội có chứa glycoprotein giúp khống chế bradykinin một chất gây viêm sưng. Ngoài ra chất gel của nha đam còn thẩm thấu vào da với lượng canxi cùng vitamin E và C giúp tái tạo da, làm lành vết thương, hạn chế tổn thương cho da.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nAzelaic acid: có đặc tính kháng khuẩn, chống viêm, vì vậy có công dụng trong điều trị các bệnh về da thường gặp như mụn trứng cá. Hơn nữa, Azelaic acid còn có giúp ngăn ngừa mụn tái phát, làm thông thoáng và sạch lỗ chân lông, nhờ đó hạn chế mụn hiệu quả.\r\n\r\nThành phần đầy đủ: Aqua, Sodium Polyacrylate, Aloe Barbadensis Leaf Extract, Hydrogenated Polydecene, Lauryl Methacrylate/Glycol Dimethacrylate Crosspolymer, Nylon-12, Cyclopentasiloxane, Simmondsia Chinensis Seed Oil, Cyclohexasiloxane, Polyisoprene, Phenoxyethanol, Caprylyl Glycol, Ethylhexylglycerin, Hydrolyzed Milk Protein, Trideceth-6, 2-Bromo-2-Nitropropane-1,3-Diol, Allantoin, Bisabolol, Glycyrrhetinic Acid, Leptospermum Scoparium Branch/Leaf Oil, Mentha Arvensis Leaf Oil, Mimosa Tenuiflora Bark Extract, Epilobium Angustifolium Flower/Leaf/Stem Extract, Calendula Officinalis Flower Extract, Glycine Soja Sterols Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'Hot', 0, 100, '2022-12-21', '2024-12-06'),
(17, 'Juliette Armand Cleansing Tonic Lotion', '17.jpg', '980000', '882000', 'Lợi ích Juliette armand cleansing tonic lotion Làm sạch lại 1 lần nữa những bụi bẩn và dầu thừa còn sót lại trên da.\r\nGiúp cân bằng độ ẩm.\r\nĐưa độ pH của da trở về mức cân bằng để có thể hấp thụ tốt nhất các dưỡng chất của các bước dưỡng sau.\r\nTái sinh da mà không làm khô hay gây kích ứng da.\r\nTrẻ hóa và se nhỏ lỗ chân lông.', 'Juliette armand cleansing tonic lotion là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Nước cân bằng dưỡng ẩm Juliette Armand Cleansing Tonic Lotion không chứa cồn và chất hoạt động bề mặt. Sản phẩm giúp cân bằng độ pH, làm sạch bụi bẩn và dầu thừa. Đồng thời tái sinh da mà không làm khô hay kích ứng da.\r\nNước cân bằng dưỡng ẩm Juliette Armand Cleansing Tonic Lotion với chiết xuất cúc La Mã giữ ẩm, chiết xuất cam đắng có tác dụng trẻ hóa da và vitamin F (Linoleic Acid) giúp thu nhỏ lỗ chân lông. Mọi người thường hay bỏ qua bước này nhưng thực chất đây lại là 1 trong những bước rất quan trọng trong chu trình làm sạch da.\r\nMọi người thường hay bỏ qua bước thoa lotion nhưng thực chất đây lại là 1 trong những bước rất quan trọng trong chu trình làm sạch da. Nó có hiệu quả loại bỏ các tạp chất và dầu nhờn trên da, đồng thời phục hồi da mà không gây khô và kích ứng. Em này không chứa cồn, chứa các thành phần lành tính làm sạch bề mặt.', 'Đối tượng Juliette armand cleansing tonic lotion Nước cân bằng da Juliette Armand Cleansing Tonic Lotion sử dụng được cho mọi loại da.', 'Hướng dẫn sử dụng Juliette armand cleansing tonic lotion Sử dụng sau bước làm sạch da.\r\n\r\nDùng bông tẩy trang tẩm lượng nhỏ sản phẩm thoa đều toàn mặt.\r\n\r\n', 'Hoa Cúc La Mã: Giảm tình trạng kích ứng, tinh dầu hoa này có đặc tính chống viêm hiệu quả do tỷ lệ azulene và bisabolol cao hơn. Bisabolol ngăn ngừa kích ứng và cung cấp hương hoa dịu nhẹ.\r\n\r\nChiết xuất từ hoa Linden: Mang lại cảm giác nhẹ nhàng. Hoa Linden thường được sử dụng để chống ngứa, bỏng, vết thương do sương giá và côn trùng cắn và giúp thư giãn làn da.\r\n\r\nVitamin F: Dưỡng ẩm, bổ sung, chứa nhiều chất chống oxy hóa, chống viêm, phục hồi hàng rào bảo vệ da.\r\n\r\nChiết xuất cam đắng: Linalool là thành phần chủ yếu và là hợp chất tạo ra mùi thơm đặc trưng của hoa cam đắng, nó được ứng dụng để làm thuốc an thần, giải phóng lo âu, giảm stress,.. Thành phần linalool có trong chiết xuất hoa cam đắng được chứng minh là không gây ra các mẫn cảm trên làn da, đặc biệt là làn da nhạy cảm.\r\n\r\nChiếc xuất cây cọ: Loại chất béo bão hòa chính có trong dầu cọ là axit palmitic, chiếm 44% lượng calo. Nó cũng chứa một lượng lớn axit oleic, lượng nhỏ axit linoleic và axit stearic. Các giống chính được sử dụng trong sản xuất dầu cọ là cây cọ dầu Elaeis guineensis, có nguồn gốc ở Tây Nam châu Phi, và cây cọ dầu Nam Mỹ Elaeis oleifera.\r\n\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn.\r\n\r\nThành phần đầy đủ: Aqua, Butylene Glycol, Chamomilla Recutita Flower Water, Tilia Cordata Flower Water, Polysorbate 20, Parfum, Ppg-26-Buteth-26, Phenoxyethanol, Peg-40 Hydrogenated Castor Oil, Vitamin Linh Kiện, Dân Tộc 4 Linh Kiện 16185, Sodium Sulfate, Ci 42051. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 0, 100, '2024-02-01', '2024-12-20'),
(18, 'Juliette Armand Elements Retinoid C Cream', '18.jpg', '1990000', '1791000', 'Lợi ích Juliette armand elements retinoid c cream Lợi ích Kem mặt Juliette Armand Retinoid C Cải thiện tình trạng lão hoá da, giúp làn da nhăn nheo trở nên bóng mượt.\r\nSửa chữa khuyết điểm trên da\r\nDuy trì giữ ẩm và tái tạo da.\r\nCải thiện tình trạng da sần sùi.\r\nCải thiện tình trạng mụn và làm đầy sẹo sau mụn.\r\nCải thiện tình trạng nám, đồi mồi, tàn nhang, thâm sau mụn…', 'Juliette armand elements retinoid c cream là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand Retinoid C đếnt ừ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam. Kem tái tạo chống oxy hóa Juliette Armand Retinoid C Cream cải thiện bề mặt da, giảm nếp nhăn bề mặt, nhăn lão hóa, nám và làm đầy sẹo do mụn trứng cá. Đồng thời củng cố sợi đàn hồi, làm da sáng rạng rỡ và bóng mượt.\r\nKem tái tạo chống oxy hóa Juliette Armand Retinoid C Cream giúp cải thiện sự xuất hiện và chất lượng của da với các đường nhăn, nếp nhăn, sự đổi màu và sẹo do mụn. Đồng thời, nó tăng cường độ đàn hồi và độ sáng của da, làm cho da sáng và tươi mới. Juliette Armand Retinoid C Cream kết hợp tác dụng sửa chữa các khuyết điểm trên da, tổn thương và rối loạn sắc tố da với sức mạnh tổng hợp của Retinoid và vitamin C, với tác dụng dưỡng ẩm của axit hyaluronic. Đặc biệt nó được làm giàu với các thành phần Vitamin E, Dầu Jojoba, Dầu mơ, Bơ hạt mỡ, Chiết xuất Centella và Panthenol, nó củng cố và bảo vệ quá trình đổi mới và hydrat hóa tự nhiên của lớp biểu bì.', 'Đối tượng Juliette armand elements retinoid c cream Đối tượng Kem mặt Juliette Armand Retinoid C Hầu hết mọi loại da trừ da dầu mụn\r\nDa lão hóa, da giữ ẩm kém.\r\nDa nhiều sắc tố sau viêm.', 'Hướng dẫn sử dụng Juliette armand elements retinoid c cream Hướng dẫn sử dụng Kem mặt Juliette Armand Retinoid C Sử dụng sau bước tinh chất. Nên kết hợp cùng tinh chất cùng loại để đạt hiệu quả tốt nhất.\r\nThoa sản phẩm lên toàn mặt 1 đến 2 lần mỗi ngày.', 'Thành phần và lưu ý Kem mặt Juliette Armand Retinoid C\r\n3-O-Ethyl Ascorbic Acid (E-AA): Là một dạng dẫn xuất bền vững của vitamin C. Nhờ có độ ổn định và độ bền cao cùng với khả năng chống lại việc sản sinh và kích hoạt men Tyrosinase cao, đồng thời giúp làm chậm quá trình sinh tổng hợp melanin trong da nên được sử dụng cho mục đích làm trắng.\r\nPanthenol: Giúp dưỡng ẩm và làm mịn da và tóc của bạn từ bên trong ở dạng ăn được và từ bên ngoài ở dạng bôi ngoài da. Panthenol là một chất hóa học được tạo ra từ axit pantothenic, còn được gọi là vitamin B5. Nó có nguồn gốc hữu cơ và cũng có thể được sản xuất từ cả nguồn thực vật và động vật. Làm dịu các tổn thương, giảm kích ứng, củng cố lớp màng lipid, duy trì độ đàn hồi cho da\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nCitric Acid: giúp kích thích tăng cường sản xuất Collagen, tăng độ đàn hồi, săn chắc của da cũng như phát huy làm sáng da, làm mờ đốm nâu an toàn, nhanh chóng. Tẩy tế bào chết và thúc đẩy việc tái tạo tế bào, giúp hình thành làn da mới.\r\nEthylhexyl Stearate: Đây là loại este có nguồn gốc từ acid béo tự nhiên Stearic Acid, có tác dụng dưỡng ẩm, bảo vệ da và tăng độ bám cho kết cấu sản phẩm. Ngoài ra, Ethylhexyl Stearate sẽ giúp da mềm mại, mịn màng và cải thiện tình trạng bóng nhờn, bết dính trên da do các loại dầu khác trong công thức gây ra\r\n\r\nThành phần đầy đủ: Aqua, C12-20 Acid Peg-8 Ester , Butylene Glycol, Glycerin, Polyglyceryl-3 Methylglucose Distearate, Cetyl Alcohol, Ethylhexyl Stearate, Prunus Armeniaca Kernel Oil, Cyclopentasiloxane, Butyrospermum Parkii Butter , Simmondsia Chinensis Seed Oil, Panthenol, Cyclohexasiloxane, Phenoxyethanol, Glycine Soja Sterols, Tocopheryl Acetate, Dimethyl Isosorbide, Caprylyl Glycol, Ethylhexylglycerin, Parfum, 3-O-Ethyl Ascorbic Acid, Dimethicone, Glyceryl Polyacrylate, Sodium Hyaluronate, Centella Asiatica Leaf Extract, Disodium Edta, Hydroxypinacolone Retinoate, Sodium Benzoate, Sodium Citrate, Citric Acid. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 0, 100, '2022-12-21', '2023-12-21'),
(19, 'Juliette Armand Elements Vitamin B Complex Serum', '19.jpg', '1100000', '990000', 'Lợi ích Juliette armand elements vitamin b complex serum Lợi ích Serum Juliette Armand Vitamin B Complex Chống sưng tấy, chống viêm, chống kích ứng mạnh\r\nLàm dịu da tức thì và sửa chữa các khiếm khuyết trên da\r\nGiúp giảm đỏ, đốm đỏ, đốm xuất huyết trên da\r\nLý tưởng cho da hỗn hợp nhạy cảm, viêm tuyến bã và giãn mao mạnh, da sau mụn hoặc tổn thương.Giúp làm dịu da ngay lập tức.\r\nCải thiện chức năng, hoạt động làn da.\r\nChống sưng tấy, chống viêm và chống kích ứng mạnh.\r\nSửa chữa những khiếm khuyết trên da, mụn trứng cá\r\nTạo sự đồng đều cấu trúc của da, làm khỏe da.\r\nLàm dày da, tăng cường tính miễn dịch cho da.\r\nHỗ trợ tổng thể các chức năng sinh lý da.', 'Juliette armand elements vitamin b complex serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Serum Juliette Armand Vitamin B Complex là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam. Tinh chất làm dịu da Juliette Armand Vitamin B Complex Serum chống sưng tấy, chống viêm, chống kích ứng mạnh, làm dịu da tức thì và sửa chữa các khiếm khuyết trên da và giúp giảm đỏ, đốm đỏ, đốm xuất huyết trên da.\r\nTinh chất làm dịu da Juliette Armand Vitamin B Complex Serum với hỗn hợp các vitamin nhóm B chống sưng tấy, chống viêm, chống kích ứng mạnh, làm dịu da tức thì và sửa chữa các khuyết điểm trên da. Điểm tạo nên sự khác biệt của dòng Vitamin B Complex của Juliette Armand đó là phù hợp cho cả da mụn. Nó dưỡng ẩm và làm dịu da khỏi kích ứng và ban đỏ. Lý tưởng cho da bị viêm da và tĩnh mạch.\r\n\r\nMột loại huyết thanh cocktail của phức hợp vitamin B có tác dụng chống viêm và chống kích ứng mạnh mẽ. B3 giúp sửa chữa các khuyết điểm trên da (nếp nhăn, mụn trứng cá thông thường và bệnh trứng cá đỏ) và mang lại sự đồng nhất và rạng rỡ. B6 có đặc tính tái tạo và chống viêm, góp phần điều trị viêm da tiết bã nhờn. MULTI B COMPLEX (B1, B2, B3, B5, B6, B12) hỗ trợ sinh lý da tổng thể. Nhờ được tăng cường với các thành phần Redyless và Panthenol, nó làm giảm mẩn đỏ và các đốm đỏ. Lý tưởng cho da bị viêm da và tĩnh mạch mạng nhện.\r\nJuliette Armand Vitamin B Complex Serum là sản phẩm cứu sinh của làn da bị mẩn đỏ.', 'Đối tượng Juliette armand elements vitamin b complex serum Đối tượng Serum Juliette Armand Vitamin B Complex Lý tưởng cho da hỗn hợp nhạy cảm, viêm tuyến bã và giãn mao mạnh, da sau mụn hoặc tổn thương.', 'Hướng dẫn sử dụng Juliette armand elements vitamin b complex serum Hướng dẫn sử dụng Serum Juliette Armand Vitamin B Complex Bước 1: Rửa mặt sạch trước khi sử dụng.\r\nBước 2: Thoa 1 lượng nhỏ sản phẩm lên da và masage cho đến khi sản phẩm được hấp thu hết.', 'Thành phần và lưu ý Serum Juliette Armand Vitamin B Complex\r\nVitamin B6 0,5%: Trị mụn là làm giảm sự sản sinh dầu thời trên da. Có tác dụng chống lại các gốc tự do ( vốn là nguyên nhân chính gây lão hóa da)\r\n\r\nVitamin B3 1%: Có khả năng bảo tồn lớp màng bảo vệ cho da tránh khỏi tình trạng bị thoát ẩm và lão hoá sớm. Duy trì độ ẩm cho da, dưỡng ẩm cho da, làm giảm sự mất nước thường xảy ra ở da.\r\n\r\nTổng hợp các vitamin B 2%: Các thành phần Vitamin nhóm B có vai trò lớn trong nhiệm vụ phục hồi tổn thương trên da, “chiến binh” vitamin B cấp tốc sửa chữa tế bào trong thời gian ngắn để trả lại làn da sáng mịn, mềm mượt tốt nhất. Có tác dụng bảo vệ làn da khỏi sự lão hoá, điều tiết tốt lượng dầu trên da để ngăn ngừa mụn hiệu quả.\r\n\r\nPanthenol 3,75%: Được xem như một loại dưỡng ẩm làm mềm, làm dịu và chống kích ứng. Nó cũng giúp da bạn xây dựng hàng rào chống lại kích ứng và mất nước.\r\n\r\nThành phần đầy đủ: Aqua, Glycerin, Panthenol, Butylene Glycol, Propanediol, Niacinamide, Phenoxyethanol, Ppg-26-Buteth-26, Glyceryl Polyacrylate, Parfum, Pyridoxine Hydrochloride, Peg-40 Hydrogenated Castor Oil, Caprylyl Glycol, Ethylhexylglycerin, Faex Extract, Potassium Hydroxide, Potassium Sorbate, Glyceryl Acrylate/ Acrylic Acid Copolymer, Pvm/Ma Copolymer, Piperonyl Glucose Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'Hot', 1000, 100, '2023-12-22', '2024-02-22'),
(20, 'Juliette Armand Eye Shine Cream', '20.jpg', '1400000', '1260000', 'ISP LCD', 'Juliette armand eye shine cream là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mắt Juliette Armand Eye Shine đến từ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam.Juliette Armand Eye Shine Cream giúp dưỡng ẩm, phục hồi, kích thích và làm sáng da. Nó cải thiện vẻ ngoài của da, giảm quầng thâm và sưng húp. Nó làm giảm sự xuất hiện của các nếp nhăn.\r\nKem đa năng đặc trị vùng mắt Juliette Armand Eye Shine Cream thúc đẩy tái tạo và làm sáng bề mặt da vùng quanh mắt, hiệu ứng chống oxy hóa rõ rệt giúp làm giảm đáng kể quầng thâm bọng mắt, làm khỏe các mao mạch, giảm sưng, sụp và làm mờ các nếp chân chim quanh mắt.\r\n\r\nJuliette Armand Eye Shine Cream được làm giàu với chiết xuất từ ​​hoa Sambucus, nó chống lại bọng mắt, quầng thâm và giảm viêm da. Ngoài ra, vitamin E và Matrixyl peptide trong nó có tác dụng làm mịn các đường biểu hiện và nếp nhăn, đồng thời kích hoạt sản xuất collagen và axit hyaluronic, do đó tăng cường độ đồng nhất của da. Nó dễ dàng hấp thụ và không gây kích ứng.\r\nSản phẩm dưỡng ẩm, thúc đẩy tái tạo và làm sáng bề mặt da vùng quanh mắt, hiệu ứng chống oxy hóa rõ rệt giúp làm giảm đáng kể quầng thâm bọng mắt, làm khỏe các mao mạch, giảm sưng, sụp. Vitamin E và peptide làm mờ các nếp chân chim quanh mắt.', 'Đối tượng Juliette armand eye shine cream Đối tượng Kem mắt Juliette Armand Eye Shine Kem đặc trị vùng mắt Juliette Armand Eye Shine Cream sử dụng để làm sáng da vùng mắt, giảm nếp chân chim.', 'Hướng dẫn sử dụng Juliette armand eye shine cream Hướng dẫn sử dụng Kem mắt Juliette Armand Eye Shine Bôi lượng nhỏ quanh mắt (không sát với mí mắt) và massage nhẹ nhàng cho đến khi sản phẩm thẩm thấu hết.', 'Axit ascorbic (Axit ascorbic 3-O Ethyl): Chống lại quá trình oxy hóa cũng như việc ức chế quá trình hình thành melanin, làm mờ sẹo, thâm, giúp da sáng mịn hơn.\r\nVitamin E: giúp chống lại tác hại của gốc tự do đồng thời ngăn chặn tác động của tia UV đối với da. Vitamin E là một hợp chất chống viêm, giúp ngừa sưng, giảm phù nề da, Ngăn chặn tình trạng phát ban và nhiều biểu hiện khác do viêm da mãn tính gây ra. Vitamin E mang đến cho da sự mịn màng, đàn hồi, khoẻ đẹp, tươi trẻ.\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nArginine: Chống oxy hóa bằng cách trung hòa các gốc tự do, các phân tử không ổn định gây hại cho da. Tăng cường hydrat hóa, hoạt động như một chất cấp ẩm cho da.\r\nHydrogenated Lecithin: Nồng độ acid béo cao trong Hydrogenated Lecithin có tác dụng như một lớp màng dưỡng ẩm & bảo vệ da.Đóng vai trò như một chất nhũ hóa, giúp hòa trộn nước & dầu trong sản phẩm.Tăng cường khả năng thâm nhập của các thành phần khác vào da.\r\n\r\nThành phần đầy đủ: Aqua, Ethylhexyl Stearate, Polyisoprene, C12-16 Alcohols, Cyclopentasiloxane, Glycerin, Glyceryl Stearate, Cyclohexasiloxane, Hydrogenated Lecithin, Palmitic Acid, 3-O-Ethyl Ascorbic Acid, Glucosyl Hesperidin, Propanediol, Phenoxyethanol, Butylene Glycol, Tocopheryl Acetate, Caprylyl Glycol, Arginine, Ethylhexylglycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium Edta, Bht, Sambucus Nigra Flower Extract, Sorbitol, Chrysanthellum Indicum Extract, Parfum, Asparagopsis Armata Extract, Carbomer, Sodium Lactate, Ascophyllum Nodosum Extract, Polysorbate 20, Potassium Sorbate, Palmitoyl Pentapeptide-4\r\n\r\nNgoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', '0', 10, 100, '2023-12-14', '2024-02-07'),
(21, 'Juliette Armand Hyaluronic Acid Serum', '21.jpg', '1100000', '990000', 'Lợi ích Serum Juliette Armand Hyaluronic Acid Xóa bỏ hầu hết các nếp nhăn theo thời gian.\r\nGiúp tăng độ đàn hồi cho da.\r\nNuôi dưỡng và giữ làn da luôn tươi trẻ, chắc khoẻ, mịn màng.\r\nThúc đẩy sự tăng trưởng tế bào da, hạn chế tình trạng lão hóa.\r\nLàm làn da trắng sáng đều màu.', 'Juliette armand hyaluronic acid serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Tinh chất dưỡng ẩm căng da Juliette Armand Hyaluronic Acid Serum khôi phục sự cân bằng nước trong da mặt và củng cố kết cấu và độ săn chắc của da. Nhờ cấu trúc phân tử axit hyaluronic trọng lượng trung bình (MMW) tạo ra một lớp màng giữ ẩm trên da làm giảm sự mất nước qua da. Đồng thời, nó góp phần vào sự toàn vẹn cấu trúc của chất nền ngoại bào của da, tạo thành một mạng lưới vững chắc hỗ trợ các sợi collagen và elastin, tăng cường độ đồng nhất và độ săn chắc của da.\r\n\r\nCác phân tử trong serum có kích thước nhỏ hơn so với thành phần có trong kem dưỡng, vì vậy nó thấm sâu vào da sâu hơn so với kem dưỡng. Vì vậy, nhiều erum được dùng để chăm sóc da và cải thiện các vấn đề đặc biệt mà kem dưỡng không thể cải thiện.\r\nJuliette Armand Hyaluronic Acid Serum với các phân tử HA cỡ trung nhỏ hơn kích thước phân tử có trong kem dưỡng, vì vậy nó thẩm thấu sâu vào da hơn, giải quyết và khắc phục được các vấn đề da thiếu ẩm và chống lão hóa sớm cho da.', 'Đối tượng Serum Juliette Armand Hyaluronic Acid Juliette Armand Hyaluronic Acid Serum an toàn và lành tính phù hợp với mọi loại da, đặc biệt là các làn da đang gặp tình trạng:\r\n\r\nLàn da khô, thiếu ẩm, nứt nẻ, bong tróc.\r\nLàn da xuất hiện các dấu hiệu lão hóa như nếp nhăn, vết chân chim, khô ráp, da xỉn màu…\r\nNhững ai đang tìm kiếm giải pháp cấp ẩm cho da tiện lợi, phù hợp cho cả ngày đêm.', 'Hướng dẫn sử dụng Serum Juliette Armand Hyaluronic Acid Sử dụng sau bước làm sạch da bằng nước tẩy trang và sữa rửa mặt.\r\nDùng toner – nước hoa hồng để cân bằng da để giúp cho da hấp thu độ ẩm tốt hơn.\r\nLấy một lượng Juliette Armand Hyaluronic Acid Serum vừa đủ thoa đều toàn mặt, kết hợp massage nhẹ nhàng cho serum dưỡng thẩm thấu vào da.\r\nKhi dùng vào buổi sáng nên kết hợp kem chống nắng để bảo vệ làn da.\r\nSử dụng đều đặn 2 lần / ngày sáng và tối để da đạt hiệu quả cao nhất.', 'MMW Hyaluronic Acid 0,2%: Là các phân tử HA cỡ trung (MMW) giúp tạo lớp màng giữ ẩm, chống mất nước qua da, tăng cường làm khỏe cấu trúc và độ săn chắc da. Lý tưởng dành cho da thường, khô mất nước.\r\nHyaluronic acid (HA) là một chất có nguồn gốc tự nhiên. Hyaluronic acid đóng vai trò là một glycosaminoglycan – một trong 3 thành phần quan trọng ở lớp hạ bì bên cạnh collagen và elastin để giữ da được trẻ trung, căng khỏe.\r\n\r\nHoạt chất này cũng là một chất giữ ẩm, có khả năng hút ẩm từ môi trường xung quanh. Do đó HA thường xuất hiện nhiều trong các dòng kem dưỡng ẩm gốc nước, serum và các sản phẩm chăm sóc da – đặc biệt dành cho da khô, da mất nước.Hyaluronic acid có khả năng chữa lành những tổn thương trên da bằng các thúc đẩy quá trình hydrat hóa da. Hyaluronic acid giúp thúc đẩy quá trình tái tạo da bằng cách cung cấp thêm độ ẩm. Điều này tự nhiên sẽ dẫn đến kết quả các tế bào da ngày càng khỏe mạnh, da từ đó cũng tương sáng hơn.\r\nThành phần đầy đủ: Aqua, Glycerin, Butylene Glycol, Phenoxyethanol, Ppg-26-Buteth-26, Glyceryl Polyacrylate, Peg-40 Hydrogenated Castor Oil, Ethylhexyloth-26, Glyceryl Polyacrylate, Peg-40 Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 2, 200, '2024-02-02', '2024-02-23'),
(22, 'Juliette Armand Hydra Bonding Serum', '22.jpg', '1200000', '1080000', 'Lợi ích Serum Juliette Armand Hydra Bonding Siêu giữ ẩm giúp tăng khả năng giữ nước kéo dài cho hiệu ứng căng bóng\r\nGiúp giảm đỏ, giảm kích ứng cho da nhạy cảm và gia tăng bảo vệ hàng rào lipid trên da.\r\nDuy trì độ ẩm hiệu quả trong điều kiện khắc nghiệt như nhiệt độ thấp và môi trường khô.', 'Juliette armand hydra bonding serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Juliette Armand Hydra Bonding Serum làm dịu da khỏi mẫn cảm và kích ứng và cung cấp độ ẩm kéo dài. Huyết thanh dưỡng ẩm và duy trì độ ẩm hiệu quả trong điều kiện khắc nghiệt như nhiệt độ thấp và môi trường khô.\r\nJuliette Armand – Một thương hiệu mỹ phẩm chất lượng đến từ Hy Lạp, một thương hiệu khởi nguồn từ khát khao tạo ra những mỹ phẩm chuyên nghiệp dành riêng cho phụ nữ của vị chủ tịch Ioulia Armagou. Theo dòng chảy thời gian và sứ mệnh làm đẹp, các dòng sản phẩm mới đã ra đời và phát triển theo hướng kích hoạt và thúc đẩy chức năng tự nhiên của làn da nhằm đem đến những trị liệu an toàn và hiệu quả nhất.\r\n\r\nSerum làm dịu dưỡng ẩm Juliette Armand Hydra Bonding Serum với các hoạt chất siêu giữ ẩm giúp tăng khả năng giữ nước kéo dài cho hiệu ứng căng bóng đặc biệt, hiệu quả ngay cả trong môi trường khắc nghiệt có độ ẩm trong không khí bất ổn hoặc khi môi trường sống thay đổi. Sản phẩm còn giúp giảm đỏ, giảm kích ứng cho da nhạy cảm và gia tăng bảo vệ hàng rào lipid trên da.', 'Đối tượng Serum Juliette Armand Hydra Bonding Serum làm dịu dưỡng ẩm Juliette Armand Hydra Bonding Serum 20ml với các thành phần lành tính, an toàn khi sử dụng, đặc biệt dùng cho tình trạng:\r\n\r\nDa nhạy cảm, da bị mẩn đỏ\r\nDa trong môi trường khắc nghiệt.', 'Hướng dẫn sử dụng Juliette armand hydra bonding serum Hướng dẫn sử dụng Serum Juliette Armand Hydra Bonding Rửa mặt sạch trước khi sử dụng serum sau đó thoa 1 lượng nhỏ sản phẩm lên da và masage cho đến khi sản phẩm được hấp thu hết', 'Antarcticin (glycoprotein): Antarcticine trong tự nhiên có chức năng bảo vệ các vi khuẩn chống lại điều kiện khắc nghiệt. Trong mỹ phẩm, thì Antarcticine sẽ giúp duy trì tính đề kháng tự nhiên và thúc đẩy tăng sinh keratinocyte và nguyên bào sợi cho một làn da căng, làm lành vết thương.\r\nPentavitin: Giúp bảo vệ làn da trong sức mạnh tổng hợp với hai loại axit hyaluronic (HMW & XSMW) tăng cường dự trữ nước của da và giảm sự mất mát qua da.\r\n\r\nDermasooth: Một hỗn hợp chiết xuất từ ​​thực vật (Enteromorpha Compressa, Silybum Marianum, Ocimum Sanctum) và Panthenol giúp giảm mẩn đỏ và bảo vệ hàng rào bảo vệ da.\r\n\r\nPanthenol: Giúp dưỡng ẩm và làm mịn da và tóc của bạn từ bên trong ở dạng ăn được và từ bên ngoài ở dạng bôi ngoài da. Panthenol là một chất hóa học được tạo ra từ axit pantothenic, còn được gọi là vitamin B5. Nó có nguồn gốc hữu cơ và cũng có thể được sản xuất từ ​​cả nguồn thực vật và động vật. Làm dịu các tổn thương, giảm kích ứng, củng cố lớp màng lipid, duy trì độ đàn hồi cho da\r\n\r\nThành phần đầy đủ: Aqua, Glycerin, Saccharide Isomerate, Butylene Glycol, Panthenol, Propanediol, Ppg-26-Buteth-26, Phenoxyethanol, Peg-40 Hydrogenated Castor Oil, Panthenol, Propanediol, Ppg-26-Buteth-26, Phenoxyethanol, Peg-40 Hydrogenated Castor Oil, Ethylhexylglycerin Cổ Thân Tinh Chất Thủy Tinh Khiết Xuất Thủy Tinh Khiết Xuất Thủy Tinh Alkyl Acrylate Crosspolymer, Sodium Hyaluronate, Disodium Edta, Potassium Sorbate, Enteromorpha Compressa Extract, Citric Acid, Sodium Citrate, Ocimum Sanctum Leaf Extract, Silybum Marianum Fruit Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 1, 100, '2024-02-07', '2024-02-29'),
(23, 'Juliette Armand Hydra Cleansing Milk', '23.jpg', '990000', '891000', 'Lợi ích Sữa rửa mặt Juliette Armand Hydra Cleansing Milk Làm sạch sâu cho da và loại bỏ các chất bã bên trong lỗ chân lông, duy trì được độ ẩm cũng như lớp màng Lipid bảo vệ da.\r\n\r\n– Có đặc tính dịu nhẹ, không gây kích ứng da.\r\n\r\n– Giảm tình trạng bít tắc lỗ chân lông và mụn\r\nSữa rửa mặt với công thức giàu độ ẩm chiết xuất từ cúc La mã và Lô hội dễ dàng làm sạch sâu cho da và loại bỏ các chất bã bên trong lỗ chân lông, mà vẫn duy trì được độ ẩm cũng như lớp màng Lipid bảo vệ da. Với đặc tính nhẹ dịu, sản phẩm không gây kích ứng da.', 'Juliette armand hydra cleansing milk là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Sữa rửa mặt Juliette Armand Hydra Cleansing Milk đến từ thương hiệu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam.Sữa rửa mặt dưỡng ẩm Juliette Armand Hydra Cleansing Milk với công thức giàu độ ẩm được chiết xuất từ cúc La mã và Lô hội dễ dàng làm sạch sâu cho da và loại bỏ các chất bã bên trong lỗ chân lông, mà vẫn duy trì được độ ẩm cũng như lớp màng Lipid bảo vệ da.\r\n\r\nJuliette Armand Hydra Cleansing Milk không chỉ giúp loại bỏ hiệu quả các tạp chất và lớp trang điểm trên da mà nó có đặc tính làm dịu an toàn với mọi làn da, không gây ra bất kỳ kích ứng nào. Sữa rửa mặt với kết cấu dạng kem đặc kết hợp hỗn hợp các loại dầu thực vật giúp làm sạch da dễ dàng và loại bỏ mà không cần dùng đến nước. Nó chứa chiết xuất từ ​​hoa cúc La Mã và lô hội xanh để làm mềm, làm dịu và dưỡng ẩm cho da.\r\nSữa rửa mặt với công thức giàu độ ẩm chiết xuất từ cúc La mã và Lô hội dễ dàng làm sạch sâu cho da và loại bỏ các chất bã bên trong lỗ chân lông, mà vẫn duy trì được độ ẩm cũng như lớp màng Lipid bảo vệ da. Với đặc tính nhẹ dịu, sản phẩm không gây kích ứng da.', 'Đối tượng Sữa rửa mặt Juliette Armand Hydra Cleansing Milk Sữa rửa mặt dưỡng ẩm Juliette Armand Hydra Cleansing Milk dành cho da dầu, da khô và da nhạy cảm.', 'Hướng dẫn sử dụng Sữa rửa mặt Juliette Armand Hydra Cleansing Thoa lượng vừa đủ lên toàn mặt, dùng các đầu ngón tay mềm massage theo vòng tròn sau đó dùng bông ẩm lau sạch đi.', 'Chiết xuất Chamomill: Hỗ trợ dưỡng ẩm ngừa da khô,làm sạch, cân bằng trạng thái của da và có tính kháng viêm, se khít lỗ chân lông giúp da mịn màng.\r\n\r\nLô hội: Tăng cường khả năng thâm nhập sâu, đưa các dưỡng chất, thành phần hoạt tính khác vào da, nhờ đó phát huy hiệu quả dưỡng da tốt hơn. Thành phần này còn được chứng minh có khả năng kích thích gia tăng nguyên bào sợi và hỗ trợ sản sinh Collagen nhiều hơn cho da săn chắc, căng mịn.\r\n\r\nArginine: Phục hồi da, giảm dấu hiệu nhạy cảm trên da.\r\n\r\nThành phần đầy đủ: Aqua, Caprylic/Capric Triglyceride, Butylene Glycol, Polysorbate 60, Sorbitan Stearate, Cetyl Alcohol, Aloe Barbadensis Leaf Extract, Chamomilla Recutita Flower Water, Phenoxyethanol, Arginine, Ethylhexylglycerin, Parfum, Caprylyl Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium Edta Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 3, 1000, '2023-02-23', '2024-02-01'),
(24, 'Juliette Armand Hydra Mattifying Gel', '24.jpg', '1050000', '945000', 'Lợi ích Juliette armand hydra mattifying gel Lợi ích Kem mặt Juliette Armand Hydra Mattifying Kiểm soát lượng dầu thừa trên da.\r\nHấp thụ dầu thừa, giảm bóng nhờn đồng thời dưỡng ẩm cho da.\r\nPhục hồi, làm lành các tổn thương trên da, cho da luôn mềm mịn và đàn hồi trở lại.\r\nThu nhỏ lỗ chân lông, làm mềm da và ngăn ngừa các tác động bên ngoài.\r\nTăng khả năng săn chắc, đàn hồi cao.\r\nKháng khuẩn, giảm viêm và điều trị các bệnh ngoài da.\r\nCó thể thay thế được lớp nền trang điểm cho các bước trang điểm rút ngắn hơn.', 'Juliette armand hydra mattifying gel là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand Hydra Mattifying Juliette Armand Hydra Mattifying Gel giúp hấp thụ dầu thừa, giảm bóng nhờn đồng thời tăng độ ẩm cho da. Vitamin B điều tiết dầu, làm dịu và thu nhỏ lỗ chân lông. Lý tưởng khi làm lớp nền trước lớp trang điểm.\r\nKem dưỡng ẩm kiềm dầu Juliette Armand Hydra Mattifying Gel là sản phẩm lý tưởng cho chị em sử dụng hằng ngày để có khả năng dưỡng ẩm hàng ngày cho da và giúp kiềm dầu. Sản phẩm phù hợp cho cả da khô và da dầu hay da hỗn hợp. Với sự kết hợp những thành phần “tinh chất” là món quà “từ đại dương” như cỏ ba lá đỏ, siêu vi bọt biển…nhanh chóng thấu sâu mang đến hiệu quả đặc biệt cho da.\r\n\r\nSản phẩm được tích hợp những công dụng lý tưởng và phù hợp cho nhiều đối tượng có những làn da khác nhau đều có thể sử dụng để kiểm soát dầu, đồng thời cung cấp những dưỡng chất để dưỡng ẩm cần thiết cho làn da.\r\n\r\nGel dưỡng ẩm kiềm dầu Juliette Armand Hydra Mattifying Gel hấp thụ dầu thừa, giảm bóng nhờn đồng thời tăng độ ẩm cho da và điều tiết dầu, làm dịu và thu nhỏ lỗ chân lông. Lý tưởng khi làm lớp nền trước lớp trang điểm.', 'Đối tượng Juliette armand hydra mattifying gel Đối tượng Kem mặt Juliette Armand Hydra Mattifying Juliette Armand Hydra Mattifying Gel với thành phần từ thiên nhiên và đặc biệt phù hợp cho nhiều đối tượng có những làn da khác nhau:\r\n\r\nĐối tượng có lượng dầu thừa tiết ra quá nhiều làm xuất hiện nhiều mụn trên da mà không được điều tiết kịp thời.\r\nĐối tượng có làn da hỗn hợp vừa tiết nhiều dầu vừa bị vấn đề khô da cần cung cấp các dưỡng chất để vừa dưỡng ẩm, vừa kiểm soát dầu.\r\nĐối tượng cần cung cấp các dưỡng chất cần thiết để tiết kiệm thời gian chăm sóc da với công năng 2 trong 1 vừa kiềm dầu vừa dưỡng ẩm cho làn da.', 'Hướng dẫn sử dụng Juliette armand hydra mattifying gel Hướng dẫn sử dụng Kem mặt Juliette Armand Hydra Mattifying Làm sạch da với tẩy trang và sữa rửa mặt.\r\nDùng toner để cân bằng da.\r\nthoa Juliette Armand Hydra Mattifying Gel với một lượng vừa đủ lên toàn bộ da, massage nhẹ nhàng cho các dưỡng chất thấm sâu vào bề mặt da.', 'Thành phần và lưu ý Kem mặt Juliette Armand Hydra Mattifying\r\nMMW Hyaluronic Acid: Nhờ khả năng dưỡng ẩm gấp 1000 lần khối lượng của nó, sức mạnh dưỡng ẩm cũng được nâng cấp lên 1000 lần. Các phân tử HA ở trạng thái cỡ trung MMW giúp chống mất nước qua da,tạo lớp màng giữ ẩm, tăng cường độ săn chắc da và củng cố cho cấu trúc da luôn được khoẻ mạnh.\r\n\r\nVitamin B tổng hợp: Các thành phần Vitamin nhóm B có vai trò lớn trong nhiệm vụ phục hồi tổn thương trên da, “chiến binh” vitamin B cấp tốc sửa chữa tế bào trong thời gian ngắn để trả lại làn da sáng mịn, mềm mượt tốt nhất. Có tác dụng bảo vệ làn da khỏi sự lão hoá, điều tiết tốt lượng dầu trên da để ngăn ngừa mụn hiệu quả.\r\n\r\nChiết xuất cỏ ba lá đỏ: Giúp làm giảm sự tích tụ bã nhờn nên điều trị , giải quyết hậu quả của việc nở rộng lỗ chân lông, điều tiết bã nhờn giúp mụn giảm đáng kể. Tăng cường sự kiên kết tế bào, củng cố kết cấu da săn chắc, cho da săn chắc, đàn hồi và ngăn ngừa lão hoá hiệu quả.\r\n\r\nSiêu vi bọt biển: Công nghệ Nano độc quyền đến từ thương hiệu Juliette Armand để điều chế bọt biển trở thành dưỡng chất tốt cho nhiẹm vụ chăm sóc và dưỡng da. Công nghệ Nano “biến hoá” các hạt bọt biển kích thước lớn lớn trở thành kích thước siêu vi, thẩm thấu vào da với tốc độ rất nhanh, hiệu quả đạt được cũng nhanh như tốc độ thẩm thấu. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 50, 1000, '2024-02-02', '2024-02-21');
INSERT INTO `products` (`idProduct`, `name`, `image`, `costPrice`, `sellingPrice`, `benifit`, `descride`, `introduce`, `object`, `instruct`, `note`, `tag`, `sellNumber`, `qttStock`, `createdAt`, `updatedAt`) VALUES
(25, 'Juliette Armand Hydra Protecting Cream', '25.jpg', '1500000', '1350000', 'Lợi ích Juliette armand hydra protecting cream Lợi ích Kem mặt Juliette Armand Hydra Protecting Cung cấp độ ẩm và nước cho da.\r\nChống oxy hóa, giảm sự xuất hiện của các dấu hiệu lão hoá.\r\nBảo vệ da trước ánh nắng và tác động môi trường.\r\nKem dễ dàng thấm sâu vào da, nuôi dưỡng và chăm sóc các tế bào da.\r\nBảo vệ hàng rào tự nhiên cho da. Nuôi dưỡng là da căng mịn khỏe mạnh.', 'Juliette armand hydra protecting cream là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem mặt Juliette Armand Hydra Protecting Kem dưỡng ẩm bảo vệ da Juliette Armand Hydra Protecting Cream chống oxy hóa và thành phần lọc UV có tính năng bảo vệ da trước ánh nắng.\r\nKem dưỡng ẩm bảo vệ da Juliette Armand Hydra Protecting Cream giúp dưỡng ẩm và bảo vệ da khỏi ánh nắng mặt trời (SPF 10), ô nhiễm và các tác nhân có hại từ môi trường. Hydra Protecting Cream – Một loại kem dưỡng ẩm vừa làm nhiệm vụ giữ ẩm cho da mà còn chứa các màng lọc chống nắng bảo vệ da được kết hợp hydrat hóa axit hyaluronic MMW, chất chống oxy hóa của vitamin C, Vitamin E và khả năng chống nắng của bộ lọc tia UVA. Hoạt động dựa trên khả năng hấp thụ chất ô nhiễm của than hoạt tính từ da và lá chắn bảo vệ được cung cấp bởi các hoạt chất chuyên biệt Detoxophane và Pollushield. Kem có kết cấu đặc, dễ dàng hấp thụ mà không để lại cặn nhờn và tăng cường bảo vệ da khỏi lão hóa sớm.', 'Đối tượng Juliette armand hydra protecting cream Đối tượng Kem mặt Juliette Armand Hydra Protecting Juliette Armand Hydra Protecting Cream là sản phẩm chăm sóc da mặt phù hợp với mọi loại da, đặc biệt các làn da đang gặp tình trạng:\r\nDa khô\r\nDa có dấu hiệu lão hóa, bắt đầu xuất hiện nếp nhăn.', 'Hướng dẫn sử dụng Juliette armand hydra protecting cream Hướng dẫn sử dụng Kem mặt Juliette Armand Hydra Protecting Sau khi làm sạch da, thoa sản phẩm lên toàn mặt và massage cho kem dưỡng thấm hết vào da.\r\nNên dùng thêm kem chống nắng để làn da được bảo vệ tối đa.', 'Thành phần và lưu ý Kem mặt Juliette Armand Hydra Protecting\r\nHyaluronic aicid MMW: tăng cường độ ẩm mà không chất nào có thể so sánh, giúp hồi phục các lớp tế bào ở bề mặt da để da trông mềm mại, mịn màng và ngậm nước hơn. Chính điều này giúp cải thiện đáng kể việc xuất hiện sớm của nếp nhăn cùng các dấu hiệu lão hóa sớm khác. Nhờ khả năng dưỡng ẩm gấp 1000 lần khối lượng của nó, sức mạnh dưỡng ẩm cũng được nâng cấp lên 1000 lần. Các phân tử Axit hyaluronic ở trạng thái cỡ trung MMW giúp chống mất nước qua da,tạo lớp màng giữ ẩm, tăng cường độ săn chắc da và củng cố cho cấu trúc da luôn được khoẻ mạnh.\r\nVitamin E: giúp chống lại tác hại của gốc tự do đồng thời ngăn chặn tác động của tia UV đối với da. Vitamin E là một hợp chất chống viêm, giúp ngừa sưng, giảm phù nề da, Ngăn chặn tình trạng phát ban và nhiều biểu hiện khác do viêm da mãn tính gây ra. Vitamin E mang đến cho da sự mịn màng, đàn hồi, khoẻ đẹp, tươi trẻ.\r\nAxit ascoricic: Không chỉ giúp làm dịu đi các vùng da bị cháy nắng, axit này còn giúp giảm bớt các nếp nhăn. Làn da của mọi người sẽ trở nên đẹp hơn sau khi sử dụng các sản phẩm có chứa Axit L-ascorbic, về lâu dài nó còn giúp chống lại các gốc tự do gây tổn thương tế bào\r\nDimethicone: giữ cho tất cả các thành phần trong một sản phẩm không bị tách rời, đồng thời tạo một kết cấu có độ mịn và mượt cho sản phẩm. Khi thoa lên da hoặc tóc, dimethicone tạo ra một hàng rào vật lý giúp giữ ẩm cho da và hạn chế tình tình tóc khô xơ.\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định.\r\n\r\nThành phần đầy đủ: Aqua, Cetearyl Isononanoate, Cyclopentasiloxane, Ethylhexyl Methoxycinnamate, Bis-Peg/Ppg-16/16 Peg/Ppg-16/16 Dimethicone, Glycerin, Glyceryl Stearate, Isopropyl Palmitate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Butyl Methoxydibenzoylmethane, Octocrylene, Polyacrylamide , Ceteareth-25, Tocopheryl Acetate, C13-14 Isoparaffin, Phenoxyethanol, Caprylic/Capric Triglyceride, Dimethicone, Parfum, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Ethylhexylglycerin, Propanediol, Laureth-7, 3-O-Ethyl Ascorbic Acid, Allantoin, Bht, Disodium Edta, Diisopropyl Adipate, Potassium Hydroxide, Sodium Hyaluronate, Lecithin, Acrylic Acid/Acrylamidomethyl Propane Sulfonic Acid Copolymer, Charcoal Powder, Dimethylmethoxy Chromanol, Glyceryl Caprylate, Xanthan Gum, Pe', 'NEW', 25, 200, '2024-02-01', '2024-02-15'),
(26, 'Juliette Armand Opsis Eye Gel', '26.jpg', '1850000', '1665000', 'Lợi ích Juliette armand opsis eye gel Lợi ích Gel mắt Juliette Armand Opsis Eye Tăng sức sống và độ sáng cho vùng da quanh mắt.\r\nTăng độ săn chắc và giảm nếp nhăn hiệu quả\r\nDưỡng ẩm và cải thiện bề mặt da sưng nề, trùng nhão, bọng mắt và quầng thâm\r\nGiúp làm sáng và đồng đều màu da.', 'Juliette armand opsis eye gel là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Gel mắt Juliette Armand Opsis Eye Gel đặc trị cho da vùng mắt Juliette Armand Opsis Eye Gel dưỡng ẩm và cải thiện bề mặt da sưng nề, trùng nhão, bọng mắt và quầng thâm, giúp làm sáng và đồng đều màu da.\r\nGel đặc trị dành cho vùng da quanh mắt Juliette Armand Opsis Eye Gel là một loại gel độc đáo mang đến sự sảng khoái tức thì cho làn da xung quanh khu vực đường viền mắt nhạy cảm, giảm bọng mắt và quầng thâm, đồng thời làm săn chắc và giảm nếp nhăn.\r\n\r\nGel giúp dưỡng ẩm và cải thiện nếp nhăn, sụp, trùng nhão, bọng mắt và quầng thâm nhờ hiệu ứng săn chắc, tăng sức sống và độ sáng cho vùng da quanh mắt nhờ thành phần được chiết xuất từ hạt dẻ ngựa kết hợp cùng nhau thai sinh học và A-Bisabolol. Sản phẩm còn được ứng dụng công nghệ siêu dẫn bảo toàn hoạt chất kích hoạt nhanh tế bào AG Hesperidi làm tăng hiệu quả làm sáng cho vùng da mắt.', 'Đối tượng Juliette armand opsis eye gel Đối tượng Gel mắt Juliette Armand Opsis Eye Gel đặc trị cho da vùng mắt Juliette Armand Opsis Eye Gel dành cho mặt da sưng nề, trùng nhão, bọng mắt và quầng thâm.\r\nVùng da quanh mắt xuất hiện nếp nhăn.', 'Hướng dẫn sử dụng Juliette armand opsis eye gel Hướng dẫn sử dụng Gel mắt Juliette Armand Opsis Eye Mở khóa xi lanh, bơm lượng gel vừa đủ ra khỏi đầu bơm cao su vào vùng da quanh mắt (tránh mí mắt). Khóa xi lanh lại và dùng đầu cao su hoặc đầu ngón tay massage nhẹ ngang các rãnh nhăn và kéo nâng chân lông mày cho đến khi sản phẩm thẩm thấu hết', 'Thành phần và lưu ý Gel mắt Juliette Armand Opsis Eye\r\nGlycerin: là một loại chất có tác dụng giữ ẩm, giúp kéo nước từ không khí vào lớp ngoài của da đến tầng lớp sâu hơn của da. Trong các sản phẩm chăm sóc da, glycerin thường được kết hợp sử dụng với chất làm ẩm, một loại chất giữ ẩm khác, để giữ cho độ ẩm mà nó hút vào da được ổn định.\r\nHạt dẻ ngựa: Bảo vệ tế bào và giảm viêm, có liên quan đến tác dụng chống lão hóa.\r\nBisabolol: Có đặc tính chống viêm, kháng khuẩn, chống oxy hóa, chống lão hóa và làm sáng da.\r\nPhenoxyethanol: được sử dụng như một chất bảo quản hoặc kháng khuẩn trong những loại mỹ phẩm khác để không làm hư hỏng hoặc mất tác dụng của sản phẩm. Giảm mụn trứng cá: Trong một số sản phẩm, phenoxyethanol kết hợp với hóa chất khác có tác dụng làm giảm đáng kể mụn trứng cá.\r\nLecithin: thường xuất hiện trong các loại kem phục hồi, kem dưỡng da cho da nhạy cảm, dễ bị tổn thương. Do Lecithin có nồng độ axit béo cao nên thành phần này có thể tạo ra một rào cản trên da giúp hút ẩm hiệu quả từ đó là mềm da và làm dịu da bị khô căng.\r\n\r\nThành phần đầy đủ: Aqua, Cyclopentasiloxane, Glycerin, C30-45 Alkyl Cetearyl Dimethicone Crosspolymer, Glucosyl Hesperidin, Sodium Polyacrylate, Phenoxyethanol, Hydrogenated Polydecene, Butylene Glycol, Mica, Caprylyl Glycol, Ethylhexylglycerin, Xanthan Gum, Ppg-26-Buteth-26, Acetyl Glutamine, Bisabolol, Lecithin, Parfum, Sorbitol, Hydrolyzed Corn Starch, Peg-40 Hydrogenated Castor Oil, Aesculus Hippocastanum Seed Extract, Ppg-5 Laureth-5, Asparagopsis Armata Extract, 1,2-Hexanediol, Bacillus/Soybean/Folic Acid Ferment Extract, Sholigopeptide-1, Sh-Oligopeptide-2, Sh-Polypeptide-1, Sh-Polypeptide-11, Sh-Polypeptide-9, Sodium Hyaluronate, Lauryl Laurate, Methyl Diisopropyl Propionamide, Ethyl Menthane Carboxamide, Menthyl Lactate, Ascophyllum Nodosum Extract, Chrysanthellum Indicum Extract, Acetyl Tetrapeptide-5, Hydrated Silica, Hydrolyzed Corn Starch Octenylsuccinate, Zea Mays Starch, Potassium Sorbate Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 10, 500, '2023-07-28', '2023-12-20'),
(27, 'Juliette Armand Sensitive Cleansing Gel', '27.jpg', '1100000', '990000', 'Lợi ích Juliette armand sensitive cleansing gel Lợi ích Sữa rửa mặt Juliette Armand Sensitive Giúp rửa sạch bụi bẩn và lớp trang điểm\r\nBảo vệ da khỏi các tác nhân có hại từ môi trường\r\nGiữ ẩm cho da, giúp da mềm mại và căng mượt.', 'Juliette armand sensitive cleansing gel là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Sữa rửa mặt Juliette Armand Sensitive đến từ thương hiêu Mỹ phẩm Juliette Armand là một sản phẩm chính ngạch do Lona chính thức phân phối từ Nhà cung cấp thị trường Việt Nam. Gel rửa mặt chuyên biệt dành cho da nhạy cảm và da vùng mắt Juliette Armand Sensitive Cleansing Gel\r\n\r\nGel rửa mặt có chứa Osmopure tăng cường tính năng làm sạch bề mặt giúp rửa sạch bụi bẩn và lớp trang điểm và bảo vệ da một cách hoàn hảo các chất độc hại và ô nhiễm không khí. Hyaluronic acid được bao bọc trong nền dầu ôliu giữ ẩm cho da, giúp da mềm mại và căng mượt.\r\n\r\nGel rửa mặt chứa chiết xuất hạt Helianthus, dầu ép lạnh thu được từ hạt Hướng dương. Loại dầu này rất thường được sử dụng trong các loại kem chống lão hóa, là nguồn cung cấp nhiều axit béo có chứa vitamin A, B1, C và E, bổ sung protein và các khoáng chất khác nhau.giúp làm dịu và giảm kích ứng da. Nó là một loại dầu chăm sóc nhẹ và dịu nhẹ, làm mềm và bảo vệ.\r\n\r\nNgoài ra, em này còn chứa chiết xuất lá Hedera Helix, một chiết xuất với nhiều thành phần có lợi. Nó làm tăng lưu thông máu trên da và chống lại vi khuẩn, nấm và ký sinh trùng. Vải cũng có tác dụng làm khô và tannin mang lại tác dụng làm se rất tốt cho việc chữa lành vết thương. Hơn nữa, chiết xuất từ ​​lá này kích thích sự hình thành của một làn da mới.', 'Đối tượng Juliette armand sensitive cleansing gel Đối tượng Sữa rửa mặt Juliette Armand Sensitive Gel rửa mặt Juliette Armand Sensitive Cleansing Gel dành cho da nhạy cảm', 'Hướng dẫn sử dụng Juliette armand sensitive cleansing gel Hướng dẫn sử dụng Sữa rửa mặt Juliette Armand Sensitive Thoa một lượng vừa đủ sản phẩm lên da mặt đang ẩm, dùng đầu ngón tay mềm mát xa nhẹ nhàng theo vòng tròn và rửa sạch bằng nước. Juliette armand sensitive cleansing gel ', 'Thành phần và lưu ý Sữa rửa mặt Juliette Armand Sensitive\r\nDầu ô liu: Cung cấp độ ẩm, giữ ẩm cho da, giúp da mềm mại và căng mượt.\r\nArginine: Chống oxy hóa bằng cách trung hòa các gốc tự do, các phân tử gây hại cho da. Tăng cường hydrat hóa, khi được đưa lên bề mặt da, hợp chất Arginine sẽ nhanh chóng lôi kéo nước và giữ chúng trong cấu trúc da.\r\nAxit Hyaluronic: Giúp giữ nước cho làn da, cải thiện độ ẩm cũng như giữ cho các sợi Collagen săn chắc, dẻo dai.\r\nPhenoxyethanol: được sử dụng như một chất bảo quản hoặc kháng khuẩn trong những loại mỹ phẩm khác để không làm hư hỏng hoặc mất tác dụng của sản phẩm. Giảm mụn trứng cá: Trong một số sản phẩm, phenoxyethanol kết hợp với hóa chất khác có tác dụng làm giảm đáng kể mụn trứng cá.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.\r\nEthylhexylglycerin:Có tác dụng dưỡng da hiệu quả, tác dụng dưỡng da của thành phần Ethylhexylglycerin là nhờ vào thành phần Glycerol có trong nó. Đây là một alcol tự nhiên giúp các tế bào da trưởng thành đúng cách. Ethylhexylglycerin có khả năng hút ẩm, hút nước, làm mềm da và ngăn ngừa được tình trạng mất nước xuyên biểu bì.\r\nThành phần đầy đủ: Aqua, Olive Oil Peg-7 Esters, Glycerin, Sucrose Laurate, Ppg-26-Buteth-26, Alcohol, Peg-40 Hydrogenated Castor Oil, Acrylates / C10-30 Alkyl Acrylate, Phụ Tùng, Cappin Pca, Ethylhexylglycerin, Disodium Edta, Glyceryl Polyacrylate, Peg-8, Butylene Glycol, Helianthus Helianthus Anuus Seed Extract, Ppg-1-Peg-9 Lauryl Glycol Ether, Helianthus Anuus Seed Extract, Ppg-1-Peg-9 Lauryl Glycol Ether, Butylene Glycol, Helianthus Helianthus Helius Seed Extract, Ppg-1-Peg-9 Lauryl Glycol Ether, Heditate Hedum Axit Hedum Ait, Hedum A Trung Tính, Axit Helix Helix Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 100, 1000, '2023-12-06', '2024-02-01'),
(28, 'Juliette Armand Skin Boosters Chronos Hydra Correct Serum', '28.jpg', '2350000', '2115000', 'Lợi ích Juliette armand skin boosters chronos hydra correct serum Lợi ích Serum Juliette Armand Hydra Correct Cung cấp độ ảm và giúp dưỡng ẩm sâu hơn.\r\nChống oxy hóa, ngăn ngừa sự hình thành của các dấu hiệu lão hoá.\r\nCấp nước tầng sâu, cái thiện cấu trúc.\r\nThúc đẩy tái tạo lớp đệm nước lý tưởng làm đầy và căng mọng da tức thì.\r\nHiệu quả giữ nước kéo dài rõ rệt. ', 'Juliette armand skin boosters chronos hydra correct serum là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Serum Juliette Armand Hydra Correct Tinh chất chống lão hóa cao cấp Juliette Armand Hydra Correct Serum cải thiện cấu trúc, thúc đẩy tái tạo lớp đệm nước lý tưởng làm đầy và căng mọng da tức thì. Hiệu quả giữ nước kéo dài rõ rệt.\r\nTinh chất chống lão hóa cao cấp Juliette Armand Hydra Correct Serum giúp dưỡng ẩm, chống oxy hóa nhờ có Hyaluronic Acid liên kết chéo đầy đủ các kích cỡ giúp cấp nước tầng sâu, cái thiện cấu trúc, thúc đẩy tái tạo lớp đệm nước lý tưởng làm đầy và căng mọng.Sản phẩm ứng dụng công nghệ siêu dẫn bảo toàn hoạt chất kích hoạt nhanh tế bào và cung cấp sự tăng cường cần thiết và cảm giác da căng.\r\n\r\nChronos Hydra Correct Serum chứa 5 kích thước phân tử khác nhau của Axit Hyaluronic để hỗ trợ và cải thiện lượng nước dự trữ của da, dưỡng ẩm sâu từ trong ra ngoài. Nó góp phần vào việc bảo vệ da chống oxy hóa với vitamin E.Đặc biệt nó kích thích sản xuất collagen và elastin với Matrixyl Morphomics.', 'Đối tượng Juliette armand skin boosters chronos hydra correct serum Tinh chất chống lão hoá Hydra Correct Serum dành cho da trưởng thành và mệt mỏi, giúp dưỡng ẩm, chống oxy hóa.', 'Hướng dẫn sử dụng Juliette armand skin boosters chronos hydra correct serum Hướng dẫn sử dụng Serum Juliette Armand Hydra Correct Lấy lượng vừa đủ, thoa đều toàn mặt và mát xa nhẹ nhàng. Sử dụng 1 đến 2 lần mỗi ngày.\r\n\r\nKhông được sử dụng trong suốt kỳ mang thai.', 'Thành phần và lưu ý Serum Juliette Armand Hydra Correct\r\nSodium Hyaluronate: Có tác dụng bảo vệ tổng hợp collagen. Ngoài ra, nó còn giúp giảm các dấu hiệu lão hóa một cách tự nhiên bằng cách giảm mất nước biểu bì liên quan đến phơi nắng, độ ẩm thấp và các yếu tố bên ngoài khác liên quan đến khô da.\r\nAldenine: Giúp phục hồi và làm dịu da, cũng như một thành phần chống lão hóa. Nó cũng thúc đẩy quá trình sản xuất collagen.\r\nVitamin E: giúp chống lại tác hại của gốc tự do đồng thời ngăn chặn tác động của tia UV đối với da. Vitamin E là một hợp chất chống viêm, giúp ngừa sưng, giảm phù nề da, Ngăn chặn tình trạng phát ban và nhiều biểu hiện khác do viêm da mãn tính gây ra. Vitamin E mang đến cho da sự mịn màng, đàn hồi, khoẻ đẹp, tươi trẻ.\r\nVitamin A: Nhờ có đặc tính chống oxy hóa của chúng sẽ tiêu diệt các gốc tự do ngăn ngừa lão hóa sớm, thúc đẩy sản xuất tế bào khỏe mạnh, giúp củng cố lớp ngoài của da.\r\nButylene glycol: hoạt động như một chất làm mềm và chất giữ ẩm và giúp giữ ẩm cho da bằng cách tạo ra một hàng rào bảo vệ trên da. Điều này cuối cùng ngăn ngừa sự mất nước và dưỡng da từ bên trong.', 'NEW', 26, 1000, '2024-01-13', '2024-02-09'),
(29, 'Kem Chống Nắng Juliette Armand Sunfilm Velvet SPF 50', '29.jpg', '1600000', '1440000', 'Lợi ích Kem chống nắng Juliette Armand Sunfilm Velvet SPF 50 Bảo vệ tối đa làn da chống lại bức xạ “UVA gây lão hóa” và “UVB gây bỏng rát” cùng bức xạ máy tính, bức xạ hồng ngoại và các loại ánh sáng từ đèn LED\r\nBảo vệ da khỏi sự mất cân bằng oxy hóa và lão hóa do ánh nắng\r\nSản phẩm có tính chịu nước rất cao.', 'Kem chống nắng Juliette Armand Sunfilm Velvet SPF 50 là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Kem chống nắng Juliette Armand Sunfilm Velvet SPF 50 Kem chống nắng dưỡng ẩm Juliette Armand Sunfilm Face Velvet SPF50 không chứa dầu, không trôi, có tính chống oxy hóa mạnh dành cho mọi loại da, giúp bảo vệ da khỏi các bức bức xạ UVA, UVB, hồng ngoại (IR), chống gốc tự do oxy hóa, lão hóa da do ánh nắng, đồng thời làm dịu và khỏe da. Sản phẩm giàu các thành phần làm dịu và chất chống oxy hóa đặc biệt, làm giảm kích ứng da và bảo vệ da khỏi bảo vệ da khỏi sự mất cân bằng oxy hóa và lão hóa do ánh nắng.\r\n\r\nSunfilm SPF30 Facial Gel là sản phẩm chống tia UV nhẹ nhàng với kết cấu tinh tế, nhanh chóng được hấp thụ trên da và không gây cảm giác nhờn. Rất thích hợp cho da nhạy cảm, da dầu ngoài ra còn có thể sử dụng với mọi loại da.', 'Đối tượng Kem chống nắng Juliette Armand Sunfilm Velvet SPF 50 Kem chống nắng dành cho da nhạy cảm và da dầu, có thể sử dụng cho mọi loại da.', 'Hướng dẫn sử dụng Kem chống nắng Juliette Armand Sunfilm Velvet SPF 50 Thoa lượng đủ dày lên da 15’ trước khi ra nắng. Tùy vào thời gian hoạt động dưới ánh nắng để thoa lại sản phẩm.', 'Vitamin E: giúp chống lại tác hại của gốc tự do đồng thời ngăn chặn tác động của tia UV đối với da. Vitamin E là một hợp chất chống viêm, giúp ngừa sưng, giảm phù nề da, Ngăn chặn tình trạng phát ban và nhiều biểu hiện khác do viêm da mãn tính gây ra. Vitamin E mang đến cho da sự mịn màng, đàn hồi, khoẻ đẹp, tươi trẻ.\r\nDầu Omega INCA: Dầu Inca có tác dụng giữ ẩm và bôi trơn cho da. Cơ thể chúng ta hấp thụ omega-3 và omega-6 dễ dàng từ da. Khi hấp thụ đủ nhiều, làn da trở nên mềm hơn, ẩm hơn, rạng rỡ hơn. Tác dụng nổi bất của dầu Inca Inchi là kháng viêm tự nhiên đối với mụn trứng cá, bệnh vẩy nến hay bệnh chàm. Dầu Sacha Inchi có hàm lượng vitamin E dạng gamma tocopherol, giúp bảo vệ làn da khỏi bức xạ tia UVB – gây tổn thương cho da. Ngoài ra, vitamin E ở trong dầu này cũng giúp giảm nám và các dạng tăng sắc tố khác. Axit linoleic tạo thành hàng rào bảo vệ da tự nhiên để ngăn tình trạng mất nước ở da. Sử dụng dầu Sacha Inchi giúp củng cố hàng rào bảo vệ da, giúp da giữ độ ẩm tốt hơn. Dầu Inca Inchi có tác dụng giữ ẩm và bôi trơn cho da. Cơ thể chúng ta hấp thụ omega-3 và omega-6 dễ dàng từ da. Khi hấp thụ đủ nhiều, làn da trở nên mềm hơn, ẩm hơn, rạng rỡ hơn.\r\nAvobenzone: là một thành phần phổ biến trong kem chống nắng hóa học. Không giống như các loại kem chống nắng hóa học khác chỉ bảo vệ khỏi tia UVB gây cháy nắng, Avobenzone còn bảo vệ da khỏi tia UVA, tia gây lão hóa sớm và ung thư da.\r\nOctocrylene: có tác dụng trung hòa bức xạ UV ảnh hưởng lên da. Octocrylene tồn tại ở dạng hợp chất hữu cơ dầu, kết cấu dày, không màu. Một số được dùng trong kem chống nắng không kê đơn. Mặc dù có nhiều công dụng nhưng chức năng chính của Octocrylene vẫn là trung hòa bức xạ UV ảnh hưởng lên da.\r\nTinosorb S: bảo vệ da khỏi tia UVA và UVB, làm cho nó trở thành một trong những thành phần lý tưởng nhất để ngăn ngừa tác hại của ánh nắng mặt trời. Tinosorb cũng giúp ổn định các bộ lọc chống nắng khác và được phép ở nồng độ lên đến 10%.\r\n\r\nThành phần khác: Octaluate, Elastome. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'NEW', 30, 1000, '2024-01-13', '2024-02-10'),
(30, 'Kem Dưỡng Ẩm Juliette Armand Hydra Mattifying', '30.jpg', '1750000', '1575000', 'Lợi ích Kem dưỡng ẩm Juliette Armand Hydra Mattifying Công nghệ thông minh giúp tiết kiệm cho quy trình chăm sóc da nhờ “tích hợp” 2 trong 1 vừa kiềm dầu vừa dưỡng ẩm.\r\nKiểm soát lượng dầu thừa trên da.\r\nHấp thụ dầu thừa, giảm bóng nhờn đồng thời dưỡng ẩm cho da.\r\nPhục hồi, làm lành các tổn thương trên da, cho da luôn mềm mịn và đàn hồi trở lại.\r\nThu nhỏ lỗ chân lông, làm mềm da và ngăn ngừa các tác động bên ngoài.\r\nTăng khả năng săn chắc, đàn hồi cao.\r\nKháng khuẩn, giảm viêm và điều trị các bệnh ngoài da.\r\nCó thể thay thế được lớp nền trang điểm cho các bước trang điểm rút ngắn hơn.', 'Kem dưỡng ẩm Juliette Armand Hydra Mattifying là một sản phẩm thuộc dòng Juliette Armand Việt Nam ủy quyền phân phối chính thức.', 'Juliette Armand Hydra Mattifying Gel giúp hấp thụ dầu thừa, giảm bóng nhờn đồng thời tăng độ ẩm cho da. Vitamin B điều tiết dầu, làm dịu và thu nhỏ lỗ chân lông. Lý tưởng khi làm lớp nền trước lớp trang điểm.\r\nKem dưỡng ẩm kiềm dầu Juliette Armand Hydra Mattifying Gel là sản phẩm lý tưởng cho chị em sử dụng hằng ngày để có khả năng dưỡng ẩm hàng ngày cho da và giúp kiềm dầu. Sản phẩm phù hợp cho cả da khô và da dầu hay da hỗn hợp. Với sự kết hợp những thành phần “tinh chất” là món quà “từ đại dương” như cỏ ba lá đỏ, siêu vi bọt biển…nhanh chóng thấu sâu mang đến hiệu quả đặc biệt cho da.\r\n\r\nSản phẩm được tích hợp những công dụng lý tưởng và phù hợp cho nhiều đối tượng có những làn da khác nhau đều có thể sử dụng để kiểm soát dầu, đồng thời cung cấp những dưỡng chất để dưỡng ẩm cần thiết cho làn da.\r\n\r\nGel dưỡng ẩm kiềm dầu Juliette Armand Hydra Mattifying Gel hấp thụ dầu thừa, giảm bóng nhờn đồng thời tăng độ ẩm cho da và điều tiết dầu, làm dịu và thu nhỏ lỗ chân lông. Lý tưởng khi làm lớp nền trước lớp trang điểm.', 'Đối tượng Kem dưỡng ẩm Juliette Armand Hydra Mattifying Da dầu, da mụn và da hỗn hợp', 'Hướng dẫn sử dụng Kem dưỡng ẩm Juliette Armand Hydra Mattifying Làm sạch da. Thoa một lượng nhỏ sản phẩm lên toàn mặt và massage nhẹ nhàng cho đến khi sản phẩm thẩm thấu hết.', 'MMW Hyaluronic Acid: Nhờ khả năng dưỡng ẩm gấp 1000 lần khối lượng của nó, sức mạnh dưỡng ẩm cũng được nâng cấp lên 1000 lần. Các phân tử HA ở trạng thái cỡ trung MMW giúp chống mất nước qua da,tạo lớp màng giữ ẩm, tăng cường độ săn chắc da và củng cố cho cấu trúc da luôn được khoẻ mạnh.\r\n\r\nVitamin B tổng hợp: Các thành phần Vitamin nhóm B có vai trò lớn trong nhiệm vụ phục hồi tổn thương trên da, “chiến binh” vitamin B cấp tốc sửa chữa tế bào trong thời gian ngắn để trả lại làn da sáng mịn, mềm mượt tốt nhất. Có tác dụng bảo vệ làn da khỏi sự lão hoá, điều tiết tốt lượng dầu trên da để ngăn ngừa mụn hiệu quả.\r\n\r\nChiết xuất cỏ ba lá đỏ: Giúp làm giảm sự tích tụ bã nhờn nên điều trị , giải quyết hậu quả của việc nở rộng lỗ chân lông, điều tiết bã nhờn giúp mụn giảm đáng kể. Tăng cường sự kiên kết tế bào, củng cố kết cấu da săn chắc, cho da săn chắc, đàn hồi và ngăn ngừa lão hoá hiệu quả.\r\n\r\nSiêu vi bọt biển: Công nghệ Nano độc quyền đến từ thương hiệu Juliette Armand để điều chế bọt biển trở thành dưỡng chất tốt cho nhiẹm vụ chăm sóc và dưỡng da. Công nghệ Nano “biến hoá” các hạt bọt biển kích thước lớn lớn trở thành kích thước siêu vi, thẩm thấu vào da với tốc độ rất nhanh, hiệu quả đạt được cũng nhanh như tốc độ thẩm thấu. Ngoài ra, bạn có thể liên hệ với chúng tôi tại Chat để được tư vấn cụ thể về từng vấn đề làn da của bạn nhé!', 'HOT', 50, 700, '2023-12-14', '2024-02-02');

